// Modo Verdadeiro/Falso: alternativa mais rápida, bom pra revisar conceitos.
export const TRUE_FALSE = [
  { id: 'tf-trindade', statement: 'A Trindade significa que existem três Deuses.', statementEn: 'The Trinity means there are three Gods.', answer: false, explanation: 'A Trindade é UM Deus em três pessoas (Pai, Filho, Espírito Santo). Triteísmo é heresia.', explanationEn: 'The Trinity is ONE God in three persons (Father, Son, Holy Spirit). Tritheism is heresy.' },
  { id: 'tf-canon-prot', statement: 'A Bíblia protestante e a católica têm o mesmo número de livros.', statementEn: 'The Protestant and Catholic Bibles have the same number of books.', answer: false, explanation: 'A católica tem 73, a protestante 66. A diferença são os 7 deuterocanônicos do AT.', explanationEn: 'The Catholic has 73, the Protestant 66. The difference is the 7 deuterocanonicals of the OT.' },
  { id: 'tf-eucaristia', statement: 'Na Eucaristia, o pão e o vinho se tornam verdadeiramente Corpo e Sangue de Cristo.', statementEn: 'In the Eucharist, the bread and wine truly become the Body and Blood of Christ.', answer: true, explanation: 'É a doutrina da Transubstanciação, ensinada desde os Padres da Igreja e definida solenemente em Latrão IV (1215) e Trento (1551).', explanationEn: 'This is the doctrine of Transubstantiation, taught since the Fathers and solemnly defined at Lateran IV (1215) and Trent (1551).' },
  { id: 'tf-papa-impec', statement: 'A infalibilidade papal significa que o Papa não pode pecar.', statementEn: 'Papal infallibility means the Pope cannot sin.', answer: false, explanation: 'Não. Significa que ele não pode errar quando define solenemente uma doutrina de fé ou moral. Papas pecam como qualquer um.', explanationEn: 'No. It means he cannot err when solemnly defining a doctrine of faith or morals. Popes sin like anyone else.' },
  { id: 'tf-maria-deusa', statement: 'Católicos consideram Maria uma deusa.', statementEn: 'Catholics consider Mary a goddess.', answer: false, explanation: 'Maria é venerada, não adorada. Adoração (latria) só a Deus; veneração (hyperdulia) a Maria; veneração comum (dulia) aos santos.', explanationEn: 'Mary is venerated, not worshipped. Worship (latria) only to God; veneration (hyperdulia) to Mary; common veneration (dulia) to saints.' },
  { id: 'tf-confissao-bib', statement: 'A confissão a um padre está na Bíblia.', statementEn: 'Confession to a priest is in the Bible.', answer: true, explanation: 'João 20,21-23: Jesus dá aos apóstolos o poder de perdoar ou reter pecados. Tiago 5,16 manda confessar uns aos outros.', explanationEn: 'John 20:21-23: Jesus gives the apostles the power to forgive or retain sins. James 5:16 commands confessing to one another.' },
  { id: 'tf-purgatorio', statement: 'O Purgatório é uma "segunda chance" após a morte para quem não se salvou.', statementEn: 'Purgatory is a "second chance" after death for those who weren\'t saved.', answer: false, explanation: 'Não. O Purgatório é purificação de quem JÁ se salvou, mas ainda tem apegos a corrigir antes de entrar no Céu.', explanationEn: 'No. Purgatory is purification of those who are ALREADY saved, but still have attachments to correct before entering Heaven.' },
  { id: 'tf-jesus-disse-cat', statement: 'Jesus disse expressamente: "Eu fundo a Igreja Católica".', statementEn: 'Jesus expressly said: "I found the Catholic Church".', answer: false, explanation: 'Não com essas palavras. Disse: "Tu és Pedro, e sobre esta pedra edificarei a minha Igreja" (Mt 16,18). "Católica" significa universal e foi usada já em Inácio de Antioquia (~107 d.C.).', explanationEn: 'Not in those words. He said: "Thou art Peter, and upon this rock I will build my church" (Mt 16:18). "Catholic" means universal and was used as early as Ignatius of Antioch (~107 AD).' },
  { id: 'tf-galileu-tortura', statement: 'Galileu foi torturado pela Inquisição.', statementEn: 'Galileo was tortured by the Inquisition.', answer: false, explanation: 'Não foi torturado. Foi questionado, retratou-se formalmente e ficou em prisão domiciliar confortável, onde continuou a publicar ciência.', explanationEn: 'He was not tortured. He was questioned, formally recanted, and was placed under comfortable house arrest, where he continued to publish science.' },
  { id: 'tf-bigbang-padre', statement: 'A teoria do Big Bang foi proposta por um sacerdote católico.', statementEn: 'The Big Bang theory was proposed by a Catholic priest.', answer: true, explanation: 'Georges Lemaître, sacerdote belga, em 1927. Inicialmente Einstein resistiu, mas depois aceitou.', explanationEn: 'Georges Lemaître, Belgian priest, in 1927. Einstein initially resisted, but later accepted.' },
  { id: 'tf-sola-fide-biblia', statement: 'A expressão "sola fide" (só pela fé) aparece literalmente na Bíblia defendendo a justificação.', statementEn: 'The phrase "sola fide" (by faith alone) appears literally in the Bible defending justification.', answer: false, explanation: 'Tiago 2,24 usa exatamente "sola fide" — mas no sentido OPOSTO: "o homem é justificado pelas obras e não pela fé somente". A expressão é bíblica; a doutrina de Lutero não.', explanationEn: 'James 2:24 uses exactly "faith alone" — but in the OPPOSITE sense: "a person is justified by works and not by faith alone". The phrase is biblical; Luther\'s doctrine is not.' },
  { id: 'tf-purgatorio-macabeus', statement: 'O Purgatório tem base no Antigo Testamento, em 2 Macabeus.', statementEn: 'Purgatory has a basis in the Old Testament, in 2 Maccabees.', answer: true, explanation: '2 Macabeus 12,44-46: Judas Macabeu manda oferecer sacrifícios pelos soldados mortos para "que fossem libertos dos pecados". Sem purgatório, essa oração seria absurda.', explanationEn: '2 Maccabees 12:44-46: Judas Maccabeus orders sacrifices for dead soldiers so they "might be delivered from their sin". Without purgatory, this prayer would be absurd.' },
  { id: 'tf-papa-sempre-infalivel', statement: 'O Papa é infalível em todas as suas declarações públicas.', statementEn: 'The Pope is infallible in all his public statements.', answer: false, explanation: 'Apenas quando fala "ex cathedra" — definindo solenemente doutrina de fé ou moral para toda a Igreja. Aconteceu poucas vezes na história (ex.: Imaculada Conceição 1854, Assunção 1950).', explanationEn: 'Only when speaking "ex cathedra" — solemnly defining doctrine of faith or morals for the whole Church. It has happened only a few times in history (e.g., Immaculate Conception 1854, Assumption 1950).' },
  { id: 'tf-jesus-25dez', statement: 'A Bíblia afirma que Jesus nasceu no dia 25 de dezembro.', statementEn: 'The Bible states that Jesus was born on December 25th.', answer: false, explanation: 'A Bíblia não menciona a data do nascimento. O 25 de dezembro foi fixado no séc. IV. Há hipóteses sobre a data real (setembro-outubro ou dezembro), mas nenhuma certeza.', explanationEn: 'The Bible does not mention the birth date. December 25 was fixed in the 4th century. There are hypotheses about the real date (September-October or December), but no certainty.' },
  { id: 'tf-bigbang-nome-hoyle', statement: 'O nome "Big Bang" foi criado pelo padre Lemaître para descrever sua teoria.', statementEn: 'The name "Big Bang" was coined by Father Lemaître to describe his theory.', answer: false, explanation: 'O nome foi criado ironicamente pelo físico Fred Hoyle em 1949, durante um programa de rádio da BBC, para criticar a teoria. Lemaître chamava sua ideia de "hipótese do átomo primordial".', explanationEn: 'The name was coined ironically by physicist Fred Hoyle in 1949, during a BBC radio broadcast, to mock the theory. Lemaître called his idea the "hypothesis of the primordial atom".' },
  { id: 'tf-confissao-anual', statement: 'A Igreja Católica obriga os fiéis a se confessarem pelo menos uma vez por ano.', statementEn: 'The Catholic Church obliges the faithful to go to confession at least once a year.', answer: true, explanation: 'É um dos Preceitos da Igreja: confessar os pecados graves ao menos uma vez no ano. O Catecismo (§2042) explica que garante a preparação espiritual mínima.', explanationEn: 'It is one of the Precepts of the Church: confess serious sins at least once a year. The Catechism (§2042) explains it ensures minimum spiritual preparation.' },
  { id: 'tf-irmaos-jesus-biologicos', statement: 'A Bíblia prova definitivamente que Jesus teve irmãos biológicos de Maria.', statementEn: 'The Bible definitively proves that Jesus had biological brothers from Mary.', answer: false, explanation: 'O grego "adelphos" e o hebraico/aramaico "ah" (irmão) podiam indicar primos ou meios-irmãos. A tradição cristã primitiva (Hegésipo, séc. II) identificou os "irmãos de Jesus" como filhos de outro José ou parentes.', explanationEn: 'The Greek "adelphos" and Hebrew/Aramaic "ah" (brother) could indicate cousins or half-brothers. Early Christian tradition (Hegesippus, 2nd century) identified the "brothers of Jesus" as sons of another Joseph or relatives.' },
  { id: 'tf-testamento-alianca', statement: 'A palavra "testamento" em "Novo Testamento" traduz o grego para "aliança".', statementEn: 'The word "testament" in "New Testament" translates the Greek word for "covenant".', answer: true, explanation: '"Testamento" traduz o grego "diatheke" (aliança), que traduz o hebraico "berith". Jesus na Última Ceia fala de "esta taça é a nova aliança no meu sangue" (Lc 22,20).', explanationEn: '"Testament" translates the Greek "diatheke" (covenant), which translates the Hebrew "berith". At the Last Supper Jesus says "this cup is the new covenant in my blood" (Lk 22:20).' },
  { id: 'tf-missa-justino', statement: 'A estrutura básica da Missa (Liturgia da Palavra + Eucaristia) já aparece no séc. II.', statementEn: 'The basic structure of the Mass (Liturgy of the Word + Eucharist) already appears in the 2nd century.', answer: true, explanation: 'Justino Mártir (~155 d.C.) descreve nas "Apologias" a assembleia dominical: leitura dos apóstolos e profetas, homilia, oração, Eucaristia com pão e vinho consagrados. Idêntico ao rito atual.', explanationEn: 'Justin Martyr (~155 AD) describes in his "Apologies" the Sunday assembly: reading from apostles and prophets, homily, prayer, Eucharist with consecrated bread and wine. Identical to the current rite.' },
  { id: 'tf-celibato-medieval', statement: 'O celibato sacerdotal é uma imposição medieval sem nenhuma raiz apostólica.', statementEn: 'Priestly celibacy is a medieval imposition with no apostolic roots.', answer: false, explanation: 'Jesus recomenda celibato "pelo Reino dos Céus" (Mt 19,12). Paulo o recomenda para o ministério (1 Cor 7). Concílios do séc. IV já o regulavam. A prática foi formalizada gradualmente, mas tem raízes no NT.', explanationEn: 'Jesus recommends celibacy "for the kingdom of heaven" (Mt 19:12). Paul recommends it for ministry (1 Cor 7). 4th-century councils already regulated it. The practice was formalized gradually, but has roots in the NT.' },
  { id: 'tf-criacao-6dias', statement: 'A Igreja Católica ensina que o mundo foi criado em seis dias literais de 24 horas.', statementEn: 'The Catholic Church teaches that the world was created in six literal 24-hour days.', answer: false, explanation: 'A Igreja permite interpretações literária e figurativa dos dias da criação. Santo Agostinho (séc. IV) já propunha que "dia" em Gênesis é simbólico. O ensino obrigatório é que Deus criou tudo do nada, não a duração.', explanationEn: 'The Church permits literal and figurative interpretations of the days of creation. St. Augustine (4th century) already proposed that "day" in Genesis is symbolic. The mandatory teaching is that God created everything from nothing, not the duration.' },
  { id: 'tf-beatificacao-canonizacao', statement: 'Beatificação e canonização são a mesma coisa com nomes diferentes.', statementEn: 'Beatification and canonization are the same thing with different names.', answer: false, explanation: 'A beatificação permite culto local ou regional e exige 1 milagre. A canonização declara o beato Santo para a Igreja universal, exige mais 1 milagre, e é uma declaração infalível e definitiva do Papa.', explanationEn: 'Beatification permits local or regional veneration and requires 1 miracle. Canonization declares the blessed one a Saint for the universal Church, requires 1 more miracle, and is an infallible, definitive declaration by the Pope.' },
  { id: 'tf-apologetica-violencia', statement: 'Apologética cristã justifica o uso de violência para defender a fé.', statementEn: 'Christian apologetics justifies the use of violence to defend the faith.', answer: false, explanation: '1 Pedro 3,15 — o versículo fundante da apologética — manda dar razão da esperança "com mansidão e respeito". Apologética é defesa intelectual, nunca coerção física.', explanationEn: '1 Peter 3:15 — the founding verse of apologetics — commands giving the reason for hope "with gentleness and respect". Apologetics is intellectual defense, never physical coercion.' },
  { id: 'tf-evolucao-alma', statement: 'Aceitar a teoria da evolução biológica é incompatível com a fé católica.', statementEn: 'Accepting the theory of biological evolution is incompatible with Catholic faith.', answer: false, explanation: 'Pio XII (1950) e João Paulo II (1996) afirmaram que a evolução é hipótese científica séria, compatível com a fé, desde que se afirme a criação especial da alma por Deus. Teistic evolution é posição legítima.', explanationEn: 'Pius XII (1950) and John Paul II (1996) stated that evolution is a serious scientific hypothesis, compatible with faith, as long as the special creation of the soul by God is affirmed. Theistic evolution is a legitimate position.' },
  { id: 'tf-niceia-canon', statement: 'O Concílio de Niceia (325) escolheu quais livros entrariam na Bíblia.', statementEn: 'The Council of Nicaea (325) chose which books would be included in the Bible.', answer: false, explanation: 'Niceia debateu a divindade de Cristo (arianismo), não o cânon. O cânon foi discutido nos Sínodos de Hipona (393) e Cartago (397). Niceia não mencionou os livros bíblicos.', explanationEn: 'Nicaea debated the divinity of Christ (Arianism), not the canon. The canon was discussed at the Synods of Hippo (393) and Carthage (397). Nicaea made no mention of biblical books.' },
  { id: 'tf-pecado-mortal-graca', statement: 'Todo pecado mortal priva o cristão da graça santificante e da amizade com Deus.', statementEn: 'Every mortal sin deprives the Christian of sanctifying grace and friendship with God.', answer: true, explanation: 'O pecado mortal rompe a relação com Deus (CIC §1855). Três condições: matéria grave, plena advertência, pleno consentimento. A confissão restitui a graça perdida.', explanationEn: 'Mortal sin breaks the relationship with God (CCC §1855). Three conditions: grave matter, full knowledge, complete consent. Confession restores the lost grace.' },
  { id: 'tf-tj-poste', statement: 'As Testemunhas de Jeová afirmam que Jesus morreu num poste, não numa cruz.', statementEn: 'Jehovah\'s Witnesses claim Jesus died on a stake, not a cross.', answer: true, explanation: 'Elas traduzem o grego "stauros" como poste vertical simples. Mas evidências arqueológicas e fontes romanas mostram que crucifixões usavam crux (forma de T ou cruz). Fragmento de calcâneo crucificado (Givat HaMivtar, 1968) confirma prego lateral.', explanationEn: 'They translate the Greek "stauros" as a simple vertical stake. But archaeological evidence and Roman sources show crucifixions used a crux (T or cross shape). The crucified heel bone (Givat HaMivtar, 1968) confirms a lateral nail.' },
  { id: 'tf-relativismo-bib', statement: 'A Bíblia apresenta um padrão de moralidade que muda completamente de acordo com a cultura e o tempo.', statementEn: 'The Bible presents a standard of morality that changes completely according to culture and time.', answer: false, explanation: 'O Decálogo (Ex 20), as Bem-Aventuranças (Mt 5) e a lei natural inscrita no coração (Rm 2,14-15) apontam para uma ética objetiva. A aplicação muda em casos concretos, o princípio não.', explanationEn: 'The Decalogue (Ex 20), the Beatitudes (Mt 5), and the natural law written in the heart (Rm 2:14-15) point to an objective ethics. The application changes in specific cases, the principle does not.' },
  { id: 'tf-resurreicao-corpo', statement: 'A fé cristã afirma a ressurreição do corpo, não apenas a imortalidade da alma.', statementEn: 'The Christian faith affirms the resurrection of the body, not just the immortality of the soul.', answer: true, explanation: 'O Credo afirma "a ressurreição da carne". Paulo em 1 Cor 15 fala de corpo ressuscitado glorioso. Jesus ressuscitou corporalmente — o túmulo estava vazio. É diferente do platonismo (alma imortal sem corpo).', explanationEn: 'The Creed affirms "the resurrection of the body". Paul in 1 Cor 15 speaks of a glorious resurrected body. Jesus rose bodily — the tomb was empty. This differs from Platonism (immortal soul without body).' },
  { id: 'tf-maria-perpetua-virg', statement: 'A virgindade perpétua de Maria é ensinada pela Igreja Católica como doutrina.', statementEn: 'The perpetual virginity of Mary is taught by the Catholic Church as doctrine.', answer: true, explanation: 'A Igreja professa Maria "sempre virgem" — antes, durante e após o parto de Jesus. Definido nos Concílios de Latrão (649) e Constantinopla II (553). Os "irmãos de Jesus" são primos ou meios-irmãos.', explanationEn: 'The Church professes Mary "ever virgin" — before, during, and after the birth of Jesus. Defined at the Councils of Lateran (649) and Constantinople II (553). The "brothers of Jesus" are cousins or half-brothers.' },
  { id: 'tf-sete-sacramentos', statement: 'A Igreja Católica tem sete sacramentos.', statementEn: 'The Catholic Church has seven sacraments.', answer: true, explanation: 'Batismo, Confirmação, Eucaristia, Penitência, Unção dos Enfermos, Ordem e Matrimônio. Definido solenemente pelo Concílio de Trento (1547).', explanationEn: 'Baptism, Confirmation, Eucharist, Penance, Anointing of the Sick, Holy Orders, and Matrimony. Solemnly defined by the Council of Trent (1547).' },
  { id: 'tf-protestantes-5sacramentos', statement: 'A maioria das igrejas protestantes reconhece cinco sacramentos.', statementEn: 'Most Protestant churches recognize five sacraments.', answer: false, explanation: 'A maioria das denominações protestantes reconhece apenas dois: Batismo e Ceia do Senhor (Eucaristia), baseando-se em instituição explícita por Cristo nos Evangelhos.', explanationEn: 'Most Protestant denominations recognize only two: Baptism and the Lord\'s Supper (Eucharist), based on explicit institution by Christ in the Gospels.' },
  { id: 'tf-niceia-trindade', statement: 'O Concílio de Nicéia (325) definiu a doutrina da Trindade em sua forma completa.', statementEn: 'The Council of Nicaea (325) defined the doctrine of the Trinity in its complete form.', answer: false, explanation: 'Nicéia definiu a consubstancialidade do Filho. A doutrina plena da Trindade (incluindo o Espírito Santo) foi completada no Concílio de Constantinopla I (381) com a divindade do Espírito Santo.', explanationEn: 'Nicaea defined the consubstantiality of the Son. The full doctrine of the Trinity (including the Holy Spirit) was completed at Constantinople I (381) with the divinity of the Holy Spirit.' },
  { id: 'tf-jesuitas-inacio', statement: 'A Companhia de Jesus (Jesuítas) foi fundada por Santo Inácio de Loyola.', statementEn: 'The Society of Jesus (Jesuits) was founded by St. Ignatius of Loyola.', answer: true, explanation: 'Inácio de Loyola fundou a Companhia de Jesus em 1540, aprovada pelo Papa Paulo III. Os Jesuítas foram fundamentais na Contrarreforma e nas missões (Francisco Xavier na Ásia, José de Anchieta no Brasil).', explanationEn: 'Ignatius of Loyola founded the Society of Jesus in 1540, approved by Pope Paul III. The Jesuits were central to the Counter-Reformation and missions (Francis Xavier in Asia, José de Anchieta in Brazil).' },
  { id: 'tf-francisco-dominicanos', statement: 'São Francisco de Assis fundou a ordem dos Dominicanos.', statementEn: 'St. Francis of Assisi founded the Dominican Order.', answer: false, explanation: 'São Francisco fundou os Franciscanos (Ordem dos Frades Menores, ~1209). Os Dominicanos foram fundados por São Domingos de Gusmão (~1216), com foco na pregação e no combate a heresias.', explanationEn: 'St. Francis founded the Franciscans (Order of Friars Minor, ~1209). The Dominicans were founded by St. Dominic (~1216), focused on preaching and combating heresies.' },
  { id: 'tf-adoracao-santos', statement: 'Católicos adoram os santos da mesma forma que adoram a Deus.', statementEn: 'Catholics worship the saints in the same way they worship God.', answer: false, explanation: 'A teologia católica distingue latria (adoração devida só a Deus), hyperdulia (veneração especial a Maria) e dulia (veneração comum aos santos). Pedir intercessão de um santo é como pedir a um amigo que reze por você.', explanationEn: 'Catholic theology distinguishes latria (worship due to God alone), hyperdulia (special veneration for Mary), and dulia (common veneration for saints). Asking a saint\'s intercession is like asking a friend to pray for you.' },
  { id: 'tf-catecismo-comprimento', statement: 'O Catecismo da Igreja Católica tem mais de 2000 parágrafos.', statementEn: 'The Catechism of the Catholic Church has more than 2,000 paragraphs.', answer: true, explanation: 'O CIC (1992) tem 2865 parágrafos, organizados em quatro pilares: o Credo, os Sacramentos, a Vida Moral e a Oração.', explanationEn: 'The CCC (1992) has 2,865 paragraphs, organized around four pillars: the Creed, the Sacraments, the Moral Life, and Prayer.' },
  { id: 'tf-papas-casados', statement: 'Nenhum Papa da história foi casado.', statementEn: 'No Pope in history was ever married.', answer: false, explanation: 'Vários papas primitivos eram casados, como São Pedro. O celibato clerical foi tornando-se norma gradualmente. O último papa casado foi Adriano II (872-882).', explanationEn: 'Several early popes were married, including St. Peter. Clerical celibacy gradually became the norm. The last married pope was Adrian II (872-882).' },
  { id: 'tf-credo-apostolico-apostolos', statement: 'O Credo Apostólico foi escrito pelos doze apóstolos, cada um contribuindo com uma frase.', statementEn: 'The Apostles\' Creed was written by the twelve apostles, each contributing one phrase.', answer: false, explanation: 'Essa é uma lenda piadosa medieval. O Credo Apostólico derivou do Símbolo Romano do séc. II-III, usado no Batismo em Roma. Reflete o ensinamento apostólico mas não foi composto pelos apóstolos.', explanationEn: 'This is a pious medieval legend. The Apostles\' Creed derived from the Roman Symbol of the 2nd-3rd century, used at Baptism in Rome. It reflects apostolic teaching but was not composed by the apostles.' },
  { id: 'tf-eucaristia-sacrificio', statement: 'A Eucaristia é o mesmo sacrifício do Calvário, re-apresentado de forma incruenta.', statementEn: 'The Eucharist is the same sacrifice of Calvary, re-presented in an unbloody manner.', answer: true, explanation: 'Concílio de Trento (1562): a Missa não é um sacrifício novo, mas o mesmo sacrifício do Calvário, tornando presente o que ocorreu uma vez para sempre na Cruz (Hb 10,10).', explanationEn: 'Council of Trent (1562): the Mass is not a new sacrifice, but the same sacrifice of Calvary, making present what occurred once for all on the Cross (Heb 10:10).' },
  { id: 'tf-papa-bispo-roma', statement: 'O primado do Papa se baseia no fato de ele ser o Bispo de Roma.', statementEn: 'The Pope\'s primacy is based on the fact that he is the Bishop of Rome.', answer: true, explanation: 'O papa é o sucessor de Pedro como Bispo de Roma, cidade onde Pedro pregou e foi martirizado. O primado romano tem base tanto na sucessão petrina (Mt 16,18) quanto na sede apostólica de Roma.', explanationEn: 'The pope is Peter\'s successor as Bishop of Rome, the city where Peter preached and was martyred. Roman primacy is based both on Petrine succession (Mt 16:18) and the apostolic see of Rome.' },
  { id: 'tf-aborto-ensino', statement: 'A Igreja Católica condena o aborto em qualquer circunstância.', statementEn: 'The Catholic Church condemns abortion in any circumstance.', answer: true, explanation: 'O Catecismo (§2270-2275) ensina que a vida humana deve ser respeitada desde a concepção. O aborto direto é "desordem moral grave". A Igreja não admite exceções, embora distinga do duplo efeito em casos médicos complexos.', explanationEn: 'The Catechism (§2270-2275) teaches that human life must be respected from conception. Direct abortion is a "grave moral disorder". The Church admits no exceptions, although it distinguishes from double effect in complex medical cases.' },
  { id: 'tf-quran-jesus-profeta', statement: 'O Alcorão reconhece Jesus como profeta e messias.', statementEn: 'The Quran recognizes Jesus as a prophet and messiah.', answer: true, explanation: 'O Alcorão chama Jesus de "Isa al-Masih" (Jesus o Messias) e o considera um dos maiores profetas. Afirma seu nascimento virginal. Nega, porém, sua divindade e sua crucificação.', explanationEn: 'The Quran calls Jesus "Isa al-Masih" (Jesus the Messiah) and considers him one of the greatest prophets. It affirms his virginal birth. However, it denies his divinity and crucifixion.' },
  { id: 'tf-igrejas-orientais-comunhao', statement: 'As Igrejas Católicas Orientais (como a Greco-Católica Ucraniana) estão em plena comunhão com Roma.', statementEn: 'The Eastern Catholic Churches (like the Ukrainian Greek Catholic Church) are in full communion with Rome.', answer: true, explanation: 'As Igrejas Católicas Orientais mantêm seus próprios ritos, teologia e disciplina (como o clero casado), mas estão em plena comunhão com o Papa. Não confundir com as Igrejas Ortodoxas, que não estão em comunhão.', explanationEn: 'Eastern Catholic Churches maintain their own rites, theology, and discipline (including married clergy), but are in full communion with the Pope. Not to be confused with Orthodox Churches, which are not in communion.' },
  { id: 'tf-pecado-original-adao', statement: 'O pecado original é transmitido pela imitação dos pecados de Adão, não por natureza.', statementEn: 'Original sin is transmitted by imitation of Adam\'s sins, not by nature.', answer: false, explanation: 'A heresia de Pelágio (séc. V) sustentava que o pecado original era apenas mau exemplo. Agostinho e o Concílio de Cartago (418) definiram que é transmitido por natureza (geração), não por imitação.', explanationEn: 'The heresy of Pelagius (5th century) held that original sin was merely bad example. Augustine and the Council of Carthage (418) defined it is transmitted by nature (generation), not by imitation.' },
  { id: 'tf-comunhao-protestante', statement: 'Protestantes em plena comunhão com a Igreja Católica podem receber a Eucaristia numa Missa católica.', statementEn: 'Protestants in goodwill toward the Catholic Church may receive Eucharist at a Catholic Mass.', answer: false, explanation: 'O Código de Direito Canônico (§844) permite a Eucaristia apenas a católicos, ou a cristãos orientais em perigo de morte. Isso reflete que a Eucaristia é sinal de unidade plena que ainda não existe entre católicos e protestantes.', explanationEn: 'The Code of Canon Law (§844) allows the Eucharist only to Catholics, or Eastern Christians in danger of death. This reflects that the Eucharist is a sign of full unity that does not yet exist between Catholics and Protestants.' },
  { id: 'tf-anjos-criaturas', statement: 'Os anjos são seres espirituais criados por Deus, superiores em natureza aos humanos.', statementEn: 'Angels are spiritual beings created by God, superior in nature to humans.', answer: true, explanation: 'O Catecismo (§328-330) ensina que anjos são criaturas puramente espirituais, inteligentes e livres. São superiores em natureza aos humanos, mas os humanos superam os anjos pela Encarnação (assumir a natureza humana).', explanationEn: 'The Catechism (§328-330) teaches that angels are purely spiritual creatures, intelligent and free. They are superior in nature to humans, but humans surpass angels through the Incarnation (assuming human nature).' },
  { id: 'tf-inquisicao-milhoes', statement: 'A Inquisição medieval matou milhões de pessoas.', statementEn: 'The medieval Inquisition killed millions of people.', answer: false, explanation: 'Historiadores como Henry Charles Lea e Henry Kamen estimam de 3.000 a 5.000 mortos em toda a história da Inquisição (séculos XIII-XIX). Os números "milhões" são mito anticatólico moderno.', explanationEn: 'Historians like Henry Charles Lea and Henry Kamen estimate 3,000 to 5,000 deaths across the entire history of the Inquisition (13th-19th centuries). The "millions" figure is a modern anti-Catholic myth.' },
  { id: 'tf-criacao-ex-nihilo', statement: 'A criação "ex nihilo" (do nada) é doutrina católica, negada pelo ateísmo e por algumas heresias antigas.', statementEn: 'Creation "ex nihilo" (from nothing) is Catholic doctrine, denied by atheism and some ancient heresies.', answer: true, explanation: 'O Credo afirma Deus "Criador do céu e da terra". O gnosticismo antigo ensinava que a matéria era co-eterna com Deus. A criação ex nihilo afirma que apenas Deus existe de forma não derivada.', explanationEn: 'The Creed affirms God as "Creator of heaven and earth". Ancient Gnosticism taught matter was co-eternal with God. Creation ex nihilo affirms that only God exists in an underived way.' },
  { id: 'tf-sacerdotes-confessar-pecados', statement: 'Sacerdotes católicos podem confessar seus pecados a outros sacerdotes.', statementEn: 'Catholic priests can confess their sins to other priests.', answer: true, explanation: 'Todo o fiel, incluindo sacerdotes e bispos, deve receber o sacramento da Reconciliação. João Paulo II era conhecido por se confessar regularmente. Não há dispensa sacramental para o clero.', explanationEn: 'Every faithful, including priests and bishops, must receive the Sacrament of Reconciliation. John Paul II was known to confess regularly. There is no sacramental dispensation for the clergy.' },
  { id: 'tf-missa-latin-obrigatorio', statement: 'Desde o Concílio Vaticano II, a Missa deve ser celebrada exclusivamente em latim.', statementEn: 'Since Vatican II, Mass must be celebrated exclusively in Latin.', answer: false, explanation: 'O Vaticano II permitiu o uso das línguas vernáculas (locais) na liturgia. O latim permanece a língua oficial da Igreja e pode ser usado, mas não é obrigatório. A Missa Tridentina (em latim) foi reautorizada por Bento XVI em 2007.', explanationEn: 'Vatican II permitted the use of vernacular (local) languages in the liturgy. Latin remains the official language of the Church and may be used, but is not required. The Tridentine Mass (in Latin) was reauthorized by Benedict XVI in 2007.' },
  { id: 'tf-limbo-dogma', statement: 'O Limbo das crianças (para bebês não batizados) é dogma definido da Igreja Católica.', statementEn: 'The Limbo of children (for unbaptized infants) is a defined dogma of the Catholic Church.', answer: false, explanation: 'O Limbo é uma hipótese teológica (nunca dogma), que a Comissão Teológica Internacional (2007) considerou que "pode ser abandonada". A Igreja espera que Deus salve as crianças não batizadas por caminhos que só Ele conhece.', explanationEn: 'Limbo is a theological hypothesis (never a dogma), which the International Theological Commission (2007) considered can "be abandoned". The Church hopes God saves unbaptized children by paths only He knows.' },
  { id: 'tf-pedro-primeiro-papa', statement: 'São Pedro é considerado pela Igreja Católica como o primeiro Papa.', statementEn: 'St. Peter is considered by the Catholic Church to be the first Pope.', answer: true, explanation: 'Jesus disse: "Tu és Pedro, e sobre esta pedra edificarei a minha Igreja; e as portas do inferno não prevalecerão contra ela" (Mt 16,18). Pedro foi o primeiro bispo de Roma e morreu mártir lá por volta de 64-68 d.C.', explanationEn: 'Jesus said: "Thou art Peter, and upon this rock I will build my church; and the gates of hell shall not prevail against it" (Mt 16:18). Peter was the first Bishop of Rome and died a martyr there around 64-68 AD.' },
  { id: 'tf-darwin-catolicismo', statement: 'Charles Darwin foi excomungado pela Igreja Católica por causa da teoria da evolução.', statementEn: 'Charles Darwin was excommunicated by the Catholic Church because of the theory of evolution.', answer: false, explanation: 'Darwin nunca foi excomungado. A Igreja nunca condenou a teoria da evolução como heresia. Até foi enterrado na Abadia de Westminster (Igreja Anglicana). A oposição veio de protestantes conservadores, não da Igreja Católica como instituição.', explanationEn: 'Darwin was never excommunicated. The Church never condemned the theory of evolution as heresy. He was even buried in Westminster Abbey (Anglican). Opposition came mainly from conservative Protestants, not from the Catholic Church as an institution.' },
  { id: 'tf-indulgencias-pecados', statement: 'As indulgências permitem ao fiel comprar o perdão dos pecados.', statementEn: 'Indulgences allow the faithful to purchase the forgiveness of sins.', answer: false, explanation: 'Indulgências remetem a pena temporal devida pelo pecado já perdoado. Não perdoam pecados — isso é feito na Confissão. O abuso de venda de indulgências (contrário ao ensinamento oficial) foi uma das causas da Reforma.', explanationEn: 'Indulgences remit the temporal punishment due for sins already forgiven. They do not forgive sins — that is done in Confession. The abuse of selling indulgences (contrary to official teaching) was one cause of the Reformation.' },
  { id: 'tf-credo-nicea-espiritu', statement: 'O Credo de Niceia-Constantinopla inclui afirmações sobre o Espírito Santo.', statementEn: 'The Nicene-Constantinopolitan Creed includes statements about the Holy Spirit.', answer: true, explanation: 'O Credo original de Nicéia (325) tinha apenas uma linha sobre o ES. Constantinopla I (381) expandiu: "o Senhor e Vivificador, que procede do Pai (e do Filho — Filioque, adicionado pelo Ocidente), que com o Pai e o Filho é adorado".', explanationEn: 'The original Nicene Creed (325) had only one line about the Holy Spirit. Constantinople I (381) expanded: "the Lord and Giver of Life, who proceeds from the Father (and the Son — Filioque, added by the West), who with the Father and Son is worshipped".' },
  { id: 'tf-mormoes-deus-humano', statement: 'Os Mórmons creem que Deus foi outrora um ser humano que evoluiu para a divindade.', statementEn: 'Mormons believe God was once a human being who evolved into divinity.', answer: true, explanation: 'A doutrina de Lorenzo Snow (profeta mórmon): "Como o homem é, Deus foi; como Deus é, o homem pode vir a ser." É incompatível com o monoteísmo cristão, onde Deus é eterno e imutável por natureza.', explanationEn: 'The doctrine of Lorenzo Snow (Mormon prophet): "As man now is, God once was; as God now is, man may be." This is incompatible with Christian monotheism, where God is eternal and unchanging by nature.' },
  { id: 'tf-vaticano-estado', statement: 'A Cidade do Vaticano é um Estado soberano reconhecido internacionalmente.', statementEn: 'Vatican City is a sovereign state recognized internationally.', answer: true, explanation: 'Pelo Tratado de Latrão (1929), a Itália reconheceu a soberania da Santa Sé sobre a Cidade do Vaticano (0,44 km²). O Vaticano tem passaportes, moeda, rádio, jornal e representações diplomáticas.', explanationEn: 'By the Lateran Treaty (1929), Italy recognized the sovereignty of the Holy See over Vatican City (0.44 km²). The Vatican has passports, currency, radio, newspaper, and diplomatic missions.' },
  { id: 'tf-hebreus-paulo', statement: 'A autoria da Carta aos Hebreus por Paulo é considerada certa pela Igreja Católica.', statementEn: 'The authorship of the Letter to the Hebrews by Paul is considered certain by the Catholic Church.', answer: false, explanation: 'A Igreja inclui Hebreus no cânon, mas não define sua autoria como dogma. Orígenes (séc. III) dizia: "só Deus sabe quem escreveu Hebreus." Candidatos incluem Paulo, Apolo, Barnabé e Priscila.', explanationEn: 'The Church includes Hebrews in the canon but does not define its authorship as dogma. Origen (3rd century) said: "only God knows who wrote Hebrews." Candidates include Paul, Apollos, Barnabas, and Priscilla.' },
  { id: 'tf-mateus-primeiro-evangelho', statement: 'O Evangelho de Mateus foi o primeiro a ser escrito, segundo o consenso atual da crítica bíblica.', statementEn: 'The Gospel of Matthew was the first to be written, according to current biblical scholarship.', answer: false, explanation: 'O consenso atual (maioria dos especialistas) é que Marcos foi escrito primeiro (~65-70 d.C.), e Mateus e Lucas usaram Marcos como fonte (hipótese das duas fontes). A tradição patrística preferia Mateus, mas os manuscritos apontam para Marcos.', explanationEn: 'Current consensus (majority of scholars) is that Mark was written first (~65-70 AD), and Matthew and Luke used Mark as a source (two-source hypothesis). Patristic tradition favored Matthew, but manuscripts point to Mark.' },
  { id: 'tf-exorcismo-existe', statement: 'A Igreja Católica possui um rito oficial de exorcismo.', statementEn: 'The Catholic Church has an official rite of exorcism.', answer: true, explanation: 'O "Rituale Romanum" contém o exorcismo maior (Exorcismus in Satanam et Angelos Apostatas), revisado em 1999 por João Paulo II. Todo bispo pode designar um padre como exorcista. Jesus realizou exorcismos (Mt 8,28-34).', explanationEn: 'The "Rituale Romanum" contains the major exorcism (Exorcismus in Satanam et Angelos Apostatas), revised in 1999 by John Paul II. Every bishop can designate a priest as exorcist. Jesus performed exorcisms (Mt 8:28-34).' },
  { id: 'tf-filioque', statement: 'O "Filioque" ("e do Filho") no Credo Niceno é uma das causas do Cisma entre Ocidente e Oriente (1054).', statementEn: 'The "Filioque" ("and the Son") in the Nicene Creed is one of the causes of the Schism between East and West (1054).', answer: true, explanation: 'O Ocidente adicionou "Filioque" (o ES procede do Pai e do Filho) sem consenso ecuménico. O Oriente considerou isso heresia e adulteração do Credo. Junto com questões de jurisdição, contribuiu para o Cisma de 1054.', explanationEn: 'The West added "Filioque" (the HS proceeds from the Father and the Son) without ecumenical consensus. The East considered it heresy and alteration of the Creed. Together with jurisdictional issues, it contributed to the 1054 Schism.' },
  { id: 'tf-santa-ceia-simbolo', statement: 'Toda denominação cristã concorda que a Ceia do Senhor é apenas um símbolo ou memorial.', statementEn: 'Every Christian denomination agrees that the Lord\'s Supper is only a symbol or memorial.', answer: false, explanation: 'Católicos e Ortodoxos ensinam presença real de Cristo. Luteranos ensinam consubstanciação. Calvino ensinava presença espiritual real. Apenas Zuínglio e alguns protestantes ensinaram puro simbolismo. Há grande diversidade cristã aqui.', explanationEn: 'Catholics and Orthodox teach real presence of Christ. Lutherans teach consubstantiation. Calvin taught real spiritual presence. Only Zwingli and some Protestants taught pure symbolism. There is great Christian diversity here.' },
  { id: 'tf-bible-literacy', statement: 'A Igreja Católica medieval proibia os leigos de ler a Bíblia.', statementEn: 'The medieval Catholic Church forbade laypeople from reading the Bible.', answer: false, explanation: 'A Igreja nunca proibiu a leitura da Bíblia em geral. Algumas traduções não autorizadas foram proibidas por razões de precisão. A Vulgata Latina era o padrão; antes da imprensa, Bíblias eram escassas. Monges e leigos educados liam os Salmos diariamente.', explanationEn: 'The Church never forbade Bible reading in general. Some unauthorized translations were banned for accuracy reasons. The Latin Vulgate was the standard; before printing, Bibles were scarce. Monks and educated laypeople read the Psalms daily.' },
  { id: 'tf-uniao-hipostatica', statement: 'A "união hipostática" refere-se à união das duas naturezas de Cristo em uma única pessoa divina.', statementEn: 'The "hypostatic union" refers to the union of Christ\'s two natures in one divine person.', answer: true, explanation: 'Definida em Calcedônia (451): Jesus é uma única pessoa (hypostasis) com duas naturezas — divina e humana — completas e sem confusão. É a fórmula teológica central da cristologia católica e ortodoxa.', explanationEn: 'Defined at Chalcedon (451): Jesus is one person (hypostasis) with two natures — divine and human — complete and without confusion. It is the central theological formula of Catholic and Orthodox Christology.' },
  { id: 'tf-orar-mortos', statement: 'Rezar pelos mortos (sufrágio) não tem nenhuma base na Sagrada Escritura.', statementEn: 'Praying for the dead (suffrages) has no basis in Sacred Scripture.', answer: false, explanation: '2 Macabeus 12,44-46 narra Judas Macabeu mandando fazer expiação pelos soldados mortos. O NT não proíbe tal prática e Paulo pede oração por Onesíforo, provavelmente já morto (2 Tm 1,18).', explanationEn: '2 Maccabees 12:44-46 recounts Judas Maccabeus ordering expiation for dead soldiers. The NT does not prohibit this practice, and Paul asks prayer for Onesiphorus, probably already dead (2 Tm 1:18).' },
  { id: 'tf-concilio-vatII-dogma', statement: 'O Concílio Vaticano II definiu novos dogmas de fé.', statementEn: 'The Second Vatican Council defined new dogmas of faith.', answer: false, explanation: 'O Vaticano II foi convocado por João XXIII como concílio pastoral, não dogmático. Não definiu nenhum dogma novo com anátemas. Seu objetivo era atualização (aggiornamento) e diálogo, não definições doutrinais infalíveis.', explanationEn: 'Vatican II was convened by John XXIII as a pastoral, not dogmatic, council. It defined no new dogmas with anathemas. Its goal was updating (aggiornamento) and dialogue, not infallible doctrinal definitions.' },
  { id: 'tf-apocalipse-joao', statement: 'O Livro do Apocalipse foi escrito pelo apóstolo João, o mesmo que escreveu o Quarto Evangelho.', statementEn: 'The Book of Revelation was written by the Apostle John, the same who wrote the Fourth Gospel.', answer: false, explanation: 'A autoria é disputada desde o séc. II. Dionísio de Alexandria notou que o grego do Apocalipse é muito diferente do Evangelho de João. A maioria dos especialistas hoje atribui o Apocalipse a "João de Patmos", figura distinta do evangelista.', explanationEn: 'Authorship has been disputed since the 2nd century. Dionysius of Alexandria noted the Greek of Revelation is very different from the Gospel of John. Most scholars today attribute Revelation to "John of Patmos," a figure distinct from the evangelist.' },
  { id: 'tf-corpus-christi', statement: 'A festa de Corpus Christi foi instituída após uma visão de Santa Juliana de Liège.', statementEn: 'The Feast of Corpus Christi was instituted following a vision of St. Juliana of Liège.', answer: true, explanation: 'Santa Juliana de Liège (séc. XIII) recebeu visões pedindo uma festa para a Eucaristia. O Papa Urbano IV instituiu oficialmente Corpus Christi em 1264. Tomás de Aquino compôs os hinos da festa (Tantum Ergo, Pange Lingua).', explanationEn: 'St. Juliana of Liège (13th century) received visions requesting a feast for the Eucharist. Pope Urban IV officially instituted Corpus Christi in 1264. Thomas Aquinas composed the hymns for the feast (Tantum Ergo, Pange Lingua).' },
  { id: 'tf-morte-cerebral-eutanasia', statement: 'A Igreja Católica considera a morte cerebral como critério lícito para declarar a morte de uma pessoa.', statementEn: 'The Catholic Church considers brain death as a licit criterion for declaring a person dead.', answer: true, explanation: 'João Paulo II (2000) e a Pontifícia Academia das Ciências aceitaram a morte encefálica como critério legítimo para declarar morte, permitindo doação de órgãos. A Igreja apoia a doação de órgãos como ato de caridade.', explanationEn: 'John Paul II (2000) and the Pontifical Academy of Sciences accepted brain death as a legitimate criterion for declaring death, allowing organ donation. The Church supports organ donation as an act of charity.' },
  { id: 'tf-espiritos-malignos', statement: 'A Igreja Católica ensina que demônios existem como seres reais, não apenas como símbolos do mal.', statementEn: 'The Catholic Church teaches that demons exist as real beings, not merely as symbols of evil.', answer: true, explanation: 'O Catecismo (§391-395) ensina que Satanás e os demônios são anjos criados bons que se tornaram maus por livre escolha. Jesus expulsou demônios (Mc 1,34). O exorcismo é um rito oficial da Igreja (Rituale Romanum).', explanationEn: 'The Catechism (§391-395) teaches that Satan and demons are good angels who became evil by free choice. Jesus cast out demons (Mk 1:34). Exorcism is an official rite of the Church (Rituale Romanum).' },
  { id: 'tf-aborto-excomunhao', statement: 'Quem procura ou realiza um aborto incorre automaticamente em excomunhão na Igreja Católica.', statementEn: 'Those who procure or perform an abortion automatically incur excommunication in the Catholic Church.', answer: true, explanation: 'Cânon 1398 do CIC: a pena de excomunhão latae sententiae (automática) recai sobre quem procura aborto com efeito. Foi leve aliviada em 2021 (Francisco reservou a absolvição a todo padre, não mais ao bispo), mas a pena persiste.', explanationEn: 'Canon 1398 of the CIC: the penalty of latae sententiae (automatic) excommunication falls on those who procure abortion with effect. It was somewhat eased in 2021 (Francis allowed any priest to absolve, not just bishops), but the penalty persists.' },
  { id: 'tf-islam-cinco-pilares', statement: 'Os cinco pilares do islã incluem a crença em Allah e Maomé, oração, jejum, esmola e peregrinação.', statementEn: 'The five pillars of Islam include belief in Allah and Muhammad, prayer, fasting, almsgiving, and pilgrimage.', answer: true, explanation: 'Os cinco pilares (Arkan al-Islam): Shahada (profissão de fé), Salat (5 orações diárias), Zakat (esmola), Sawm (jejum do Ramadã) e Hajj (peregrinação a Meca). Estrutura básica da prática islâmica.', explanationEn: 'The five pillars (Arkan al-Islam): Shahada (profession of faith), Salat (5 daily prayers), Zakat (almsgiving), Sawm (Ramadan fast), and Hajj (pilgrimage to Mecca). The basic structure of Islamic practice.' },
  { id: 'tf-protestantes-oracao-mortos', statement: 'As principais denominações protestantes ensinam a oração pelos mortos.', statementEn: 'The main Protestant denominations teach prayer for the dead.', answer: false, explanation: 'A maioria dos protestantes rejeita a oração pelos mortos porque rejeita o purgatório. Para eles, o destino eterno é fixado na morte. A prática é exclusiva das Igrejas com tradição de purgatório (Católica, Ortodoxa, algumas anglicanas).', explanationEn: 'Most Protestants reject prayer for the dead because they reject purgatory. For them, the eternal destiny is fixed at death. The practice is exclusive to Churches with a tradition of purgatory (Catholic, Orthodox, some Anglicans).' },
  { id: 'tf-sacerdocio-universal', statement: 'O sacerdócio universal dos fiéis (1 Pd 2,9) elimina a necessidade do sacerdócio ministerial ordenado.', statementEn: 'The universal priesthood of the faithful (1 Pt 2:9) eliminates the need for ordained ministerial priesthood.', answer: false, explanation: 'O Vaticano II (Lumen Gentium §10) distingue dois sacerdócios que "diferem essencialmente e não apenas em grau": o sacerdócio batismal de todos os fiéis e o sacerdócio ministerial ordenado. Um não substitui o outro.', explanationEn: 'Vatican II (Lumen Gentium §10) distinguishes two priesthoods that "differ essentially and not only in degree": the baptismal priesthood of all the faithful and the ordained ministerial priesthood. One does not replace the other.' },
  { id: 'tf-crisma-pentecostes-pessoal', statement: 'A Confirmação é chamada o "Pentecostes pessoal" de cada cristão.', statementEn: 'Confirmation is called the "personal Pentecost" of every Christian.', answer: true, explanation: 'A Confirmação completa o Batismo e confere os dons do Espírito Santo ao fiel maduro para testemunhar a fé. É o Pentecostes de cada cristão — a efusão plena do Espírito sobre o indivíduo, como no Pentecostes para a Igreja.', explanationEn: 'Confirmation completes Baptism and confers the gifts of the Holy Spirit on the mature faithful to witness the faith. It is each Christian\'s Pentecost — the full outpouring of the Spirit on the individual, as at Pentecost for the Church.' },
  { id: 'tf-velho-testamento-abolido', statement: 'Jesus aboliu completamente o Antigo Testamento quando disse "cumpri-me a lei".', statementEn: 'Jesus completely abolished the Old Testament when he said he came to "fulfill the law".', answer: false, explanation: 'Mateus 5,17: "Não penseis que vim abolir a Lei e os Profetas; não vim abolir, mas cumprir." Jesus cumpriu o AT em si mesmo (as profecias, os tipos, a lei). O AT permanece Palavra de Deus, interpretado agora em Cristo.', explanationEn: 'Matthew 5:17: "Do not think that I have come to abolish the Law or the Prophets; I have not come to abolish them but to fulfill them." Jesus fulfilled the OT in himself (prophecies, types, law). The OT remains God\'s Word, now interpreted in Christ.' },
  { id: 'tf-maria-medianeira', statement: 'O título "Mediadora de Todas as Graças" para Maria é dogma definido da Igreja Católica.', statementEn: 'The title "Mediatrix of All Graces" for Mary is a defined dogma of the Catholic Church.', answer: false, explanation: 'Não é dogma definido — é título devocional e teológico possível, mas não proclamado solenemente. Há um movimento para uma 5ª definição mariana, mas permanece controverso. O único Mediador necessário é Cristo (1 Tm 2,5).', explanationEn: 'It is not a defined dogma — it is a possible devotional and theological title, but not solemnly proclaimed. There is a movement for a 5th Marian definition, but it remains controversial. The only necessary Mediator is Christ (1 Tm 2:5).' },
  { id: 'tf-catolicismo-maior-religiao', statement: 'O catolicismo romano é a maior denominação cristã do mundo.', statementEn: 'Roman Catholicism is the largest Christian denomination in the world.', answer: true, explanation: 'Com ~1,3 bilhão de fiéis (Anuário Pontificio 2023), o catolicismo romano é a maior denominação cristã e a maior religião organizada do mundo, presente em todos os países.', explanationEn: 'With ~1.3 billion faithful (Pontifical Yearbook 2023), Roman Catholicism is the largest Christian denomination and the largest organized religion in the world, present in every country.' },
  { id: 'tf-ccc-novo-testamento', statement: 'O Novo Testamento foi escrito completamente em grego koiné.', statementEn: 'The New Testament was written entirely in Koine Greek.', answer: true, explanation: 'Todos os 27 livros do NT foram escritos em grego koiné (comum), a língua franca do Mediterrâneo no séc. I. Não em aramaico (que Jesus falava) nem hebraico, mas no idioma internacional da época.', explanationEn: 'All 27 books of the NT were written in Koine Greek (common), the lingua franca of the Mediterranean in the 1st century. Not in Aramaic (which Jesus spoke) or Hebrew, but in the international language of the time.' },
  { id: 'tf-missa-sacrificio-novo', statement: 'A Missa é um novo sacrifício diferente e adicional ao da Cruz.', statementEn: 'The Mass is a new and additional sacrifice different from that of the Cross.', answer: false, explanation: 'Concílio de Trento (1562): a Missa não é um sacrifício novo. É o mesmo e único sacrifício do Calvário, tornado presente de forma incruenta. Hebreus 10,10: "fomos santificados pela oferenda do Corpo de Jesus Cristo uma vez por todas".', explanationEn: 'Council of Trent (1562): the Mass is not a new sacrifice. It is the same and only sacrifice of Calvary, made present in an unbloody manner. Hebrews 10:10: "we have been sanctified through the offering of the body of Jesus Christ once for all".' },
  { id: 'tf-leitura-biblia-merito', statement: 'A leitura da Bíblia é altamente recomendada pelo Magistério da Igreja.', statementEn: 'Bible reading is highly recommended by the Church\'s Magisterium.', answer: true, explanation: '"Dei Verbum" §25 (Vaticano II): "a leitura da Sagrada Escritura deve ser acompanhada de oração". "A ignorância das Escrituras é ignorância de Cristo" (São Jerônimo, citado por Bento XVI).', explanationEn: '"Dei Verbum" §25 (Vatican II): "the reading of Sacred Scripture ought to be accompanied by prayer". "Ignorance of the Scriptures is ignorance of Christ" (St. Jerome, cited by Benedict XVI).' },
  { id: 'tf-santidade-todos', statement: 'A santidade é uma vocação universal para todos os batizados, não apenas para religiosos.', statementEn: 'Holiness is a universal vocation for all the baptized, not only for religious.', answer: true, explanation: '"Lumen Gentium" §40 (Vaticano II): "todos os fiéis, de qualquer estado ou classe, são chamados à plenitude da vida cristã e à perfeição do amor." João Paulo II em "Novo Millennio Ineunte" (2001) chamou-a de "pedagogia da santidade".', explanationEn: '"Lumen Gentium" §40 (Vatican II): "all the faithful of Christ of whatever rank or status, are called to the fullness of the Christian life and to the perfection of charity." John Paul II in "Novo Millennio Ineunte" (2001) called it a "pedagogy of holiness".' },
  { id: 'tf-reforma-protestante-biblia', statement: 'A Reforma Protestante foi possibilitada em parte pela invenção da imprensa de Gutenberg.', statementEn: 'The Protestant Reformation was made possible in part by Gutenberg\'s printing press invention.', answer: true, explanation: 'Gutenberg inventou a prensa de tipos móveis ~1440. As 95 Teses de Lutero (1517) se espalharam pela Europa em semanas — impossível sem a imprensa. A reforma foi o primeiro grande evento histórico amplificado pela mídia de massa.', explanationEn: 'Gutenberg invented movable type printing ~1440. Luther\'s 95 Theses (1517) spread across Europe in weeks — impossible without the printing press. The Reformation was the first major historical event amplified by mass media.' },
  { id: 'tf-pregacao-apostolos', statement: 'Os apóstolos pregaram o Evangelho apenas a judeus, nunca a gentios.', statementEn: 'The apostles preached the Gospel only to Jews, never to Gentiles.', answer: false, explanation: 'Atos 10-11: Pedro batizou Cornélio, o centurião romano — primeiro gentio. Paulo foi o "apóstolo dos gentios" (Rm 11,13). Mateus 28,19: "ide e fazei discípulos de todas as nações (gente)".', explanationEn: 'Acts 10-11: Peter baptized Cornelius, the Roman centurion — first Gentile. Paul was the "apostle to the Gentiles" (Rm 11:13). Matthew 28:19: "go and make disciples of all nations (Gentiles)".' },
  { id: 'tf-paulo-escravidade', statement: 'Paulo ensinou que a escravidão é um bem social positivo e a apoiou explicitamente.', statementEn: 'Paul taught that slavery is a positive social good and explicitly supported it.', answer: false, explanation: 'Paulo afirma igualdade em Cristo: "Não há judeu nem grego, escravo nem livre" (Gl 3,28). Em Filemon, pede a Filemom que receba Onésimo "não mais como escravo, mas como irmão amado" (Fm 16). Paulo operava dentro de seu contexto sem uma agenda abolicionista formal.', explanationEn: 'Paul affirms equality in Christ: "There is neither Jew nor Greek, slave nor free" (Gal 3:28). In Philemon, he asks Philemon to receive Onesimus "no longer as a slave, but better than a slave, as a dear brother" (Phm 16). Paul worked within his context without a formal abolitionist agenda.' },
  { id: 'tf-criacao-tempo', statement: 'O tempo em si foi criado por Deus junto com o universo, não existia antes da criação.', statementEn: 'Time itself was created by God along with the universe, it did not exist before creation.', answer: true, explanation: 'Agostinho nas "Confissões" (XI,13): "o mundo não foi criado no tempo, mas com o tempo." Deus é eterno (além do tempo). O Big Bang criou espaço, matéria e tempo simultaneamente — Einstein confirmou que espaço-tempo são inseparáveis.', explanationEn: 'Augustine in "Confessions" (XI,13): "the world was not made in time but with time." God is eternal (beyond time). The Big Bang created space, matter, and time simultaneously — Einstein confirmed that space-time are inseparable.' },
  { id: 'tf-teresa-avila-doutora', statement: 'Santa Teresa de Ávila e Santa Teresa de Lisieux são ambas Doutoras da Igreja.', statementEn: 'St. Teresa of Ávila and St. Thérèse of Lisieux are both Doctors of the Church.', answer: true, explanation: 'Teresa de Ávila: primeira mulher Doutora da Igreja (Paulo VI, 1970), junto com Catarina de Sena. Teresa de Lisieux: Doutora da Igreja em 1997 (João Paulo II). Atualmente há 37 Doutores da Igreja, dos quais 4 são mulheres.', explanationEn: 'Teresa of Ávila: first female Doctor of the Church (Paul VI, 1970), along with Catherine of Siena. Thérèse of Lisieux: Doctor of the Church in 1997 (John Paul II). There are currently 37 Doctors of the Church, 4 of whom are women.' },
  { id: 'tf-rezar-inimigos', statement: 'Jesus mandou rezar pelos inimigos e perseguidores.', statementEn: 'Jesus commanded praying for enemies and persecutors.', answer: true, explanation: 'Mateus 5,44: "Amai os vossos inimigos, rezai pelos que vos perseguem." É um dos ensinamentos mais radicais de Jesus, invertendo a lógica humana natural ("amar quem vos ama qualquer um pode").', explanationEn: 'Matthew 5:44: "Love your enemies and pray for those who persecute you." It is one of Jesus\'s most radical teachings, inverting natural human logic ("loving those who love you, anyone can do").' },
  { id: 'tf-seculo-iv-ecumenismo', statement: 'O movimento ecumênico moderno entre cristãos teve início principalmente no séc. XXI.', statementEn: 'The modern ecumenical movement among Christians began mainly in the 21st century.', answer: false, explanation: 'O ecumenismo moderno iniciou no séc. XX com a Conferência Missionária de Edimburgo (1910) e o Conselho Mundial de Igrejas (1948). O Vaticano II (1962-65) com o decreto "Unitatis Redintegratio" marcou a entrada oficial da Igreja Católica no diálogo.', explanationEn: 'Modern ecumenism began in the 20th century with the Edinburgh Missionary Conference (1910) and the World Council of Churches (1948). Vatican II (1962-65) with the decree "Unitatis Redintegratio" marked the official entry of the Catholic Church into dialogue.' },
  { id: 'tf-orar-linguas', statement: 'O dom de línguas descrito em 1 Coríntios 14 é idêntico ao dom de línguas de Atos 2.', statementEn: 'The gift of tongues described in 1 Corinthians 14 is identical to the gift of tongues in Acts 2.', answer: false, explanation: 'Em Atos 2 todos entendiam em seu próprio idioma (línguas conhecidas). Em 1 Cor 14 Paulo fala de um dom que exige interpretação e não edifica sem ela (glossolalia como oração pessoal). Muitos teólogos os distinguem.', explanationEn: 'In Acts 2 everyone understood in their own language (known tongues). In 1 Cor 14 Paul speaks of a gift requiring interpretation and not edifying without it (glossolalia as personal prayer). Many theologians distinguish them.' },
  { id: 'tf-catolicismo-razao', statement: 'A fé católica é contrária à razão e à filosofia.', statementEn: 'The Catholic faith is opposed to reason and philosophy.', answer: false, explanation: 'A Igreja sempre integrou fé e razão. Tomás de Aquino sintetizou Aristóteles com a fé cristã. João Paulo II em "Fides et Ratio" (1998): "fé e razão são como duas asas pelas quais o espírito humano se eleva à contemplação da verdade".', explanationEn: 'The Church has always integrated faith and reason. Thomas Aquinas synthesized Aristotle with Christian faith. John Paul II in "Fides et Ratio" (1998): "Faith and reason are like two wings on which the human spirit rises to the contemplation of truth".' },
  { id: 'tf-novo-testamento-aramaico', statement: 'Jesus falava aramaico, mas os apóstolos escreveram o NT em hebraico.', statementEn: 'Jesus spoke Aramaic, but the apostles wrote the NT in Hebrew.', answer: false, explanation: 'Jesus falava aramaico (alguns termos são preservados: "Abba", "Talitha kumi", "Eli, Eli, lama sabachthani"). O NT foi escrito em grego koiné — a língua internacional do séc. I — para alcançar todo o Mediterrâneo.', explanationEn: 'Jesus spoke Aramaic (some terms are preserved: "Abba", "Talitha kumi", "Eli, Eli, lama sabachthani"). The NT was written in Koine Greek — the international language of the 1st century — to reach the entire Mediterranean.' },
  { id: 'tf-pao-divido', statement: 'O "partir o pão" nos Atos dos Apóstolos refere-se à Eucaristia.', statementEn: 'The "breaking of bread" in the Acts of the Apostles refers to the Eucharist.', answer: true, explanation: 'Atos 2,42.46; 20,7: "perseveravam na doutrina dos apóstolos, na comunhão, na fração do pão e nas orações". A "fração do pão" é o termo técnico cristão primitivo para a Eucaristia, diferente da refeição comum.', explanationEn: 'Acts 2:42,46; 20:7: "they devoted themselves to the apostles\' teaching, fellowship, the breaking of bread, and the prayers". The "breaking of bread" is the early Christian technical term for the Eucharist, different from a common meal.' },
  { id: 'tf-jesus-politico', statement: 'Jesus tinha um programa político de libertação nacional de Israel do domínio romano.', statementEn: 'Jesus had a political program for the national liberation of Israel from Roman rule.', answer: false, explanation: 'Jesus rejeitou a coroação como rei político (Jo 6,15). "Dai a César o que é de César" (Mt 22,21). Seu Reino "não é deste mundo" (Jo 18,36). Os zelotes queriam um messias político; Jesus ofereceu algo maior: redenção espiritual universal.', explanationEn: 'Jesus rejected being crowned as a political king (Jn 6:15). "Render to Caesar the things that are Caesar\'s" (Mt 22:21). His Kingdom "is not of this world" (Jn 18:36). The Zealots wanted a political messiah; Jesus offered something greater: universal spiritual redemption.' },
  { id: 'tf-biblia-completa-antes-jesus', statement: 'Toda a Bíblia (AT e NT) já existia antes da vinda de Jesus.', statementEn: 'The entire Bible (OT and NT) already existed before the coming of Jesus.', answer: false, explanation: 'O AT (com 46 livros) já existia. O NT (27 livros) foi escrito pelos apóstolos e seus companheiros após a Ressurreição (~50-100 d.C.). O cânon do NT só foi definitivamente fixado nos sínodos de Hipona (393) e Cartago (397).', explanationEn: 'The OT (with 46 books) already existed. The NT (27 books) was written by the apostles and their companions after the Resurrection (~50-100 AD). The NT canon was definitively fixed only at the synods of Hippo (393) and Carthage (397).' },
  { id: 'tf-deus-criou-mal', statement: 'Deus criou o mal assim como criou o bem.', statementEn: 'God created evil just as he created good.', answer: false, explanation: 'Agostinho: o mal não é uma substância criada, mas privatio boni — ausência/privação do bem. Deus criou apenas o bem; o mal é a corrupção do bem pela vontade livre das criaturas. Isaías 45,7 ("Eu criei o mal") refere-se a desgraças (castigos), não ao mal moral.', explanationEn: 'Augustine: evil is not a created substance but privatio boni — absence/privation of good. God created only good; evil is the corruption of good by the free will of creatures. Isaiah 45:7 ("I create evil") refers to calamities (punishments), not moral evil.' },
  { id: 'tf-santos-olimpo', statement: 'A veneração de santos na Igreja Católica é uma sobrevivência do paganismo greco-romano.', statementEn: 'The veneration of saints in the Catholic Church is a survival of Greco-Roman paganism.', answer: false, explanation: 'A veneração dos mártires começa no séc. II (martírio de Policarpo, ~156 d.C.) como celebração anual junto ao túmulo. Tem raízes no AT (culto dos profetas e patriarcas) e no NT (Hb 11-12: "nuvem de testemunhas"). Não é adoração nem herança pagã.', explanationEn: 'Veneration of martyrs begins in the 2nd century (martyrdom of Polycarp, ~156 AD) as annual celebration at the tomb. It has roots in the OT (cult of prophets and patriarchs) and NT (Heb 11-12: "cloud of witnesses"). It is not worship nor pagan heritage.' },
  { id: 'tf-livres-arbitrio-deus', statement: 'A Igreja Católica ensina que o livre-arbítrio humano é compatível com a providência divina.', statementEn: 'The Catholic Church teaches that human free will is compatible with divine providence.', answer: true, explanation: 'O Catecismo (§306-308) ensina que a providência divina governa tudo, respeitando as causas livres. Deus não coage a vontade humana, mas coopera com ela. É um mistério, não uma contradição — Deus age como causa primeira, o humano como causa segunda.', explanationEn: 'The Catechism (§306-308) teaches that divine providence governs all things, respecting free causes. God does not coerce the human will but cooperates with it. It is a mystery, not a contradiction — God acts as first cause, the human as secondary cause.' },
  { id: 'tf-missa-sacrificio', statement: 'A Missa Católica é considerada um novo sacrifício, diferente e separado do sacrifício de Cristo na Cruz.', statementEn: 'The Catholic Mass is considered a new sacrifice, different and separate from Christ\'s sacrifice on the Cross.', answer: false, explanation: 'O Catecismo (§1367) ensina que a Missa é a re-apresentação sacramental — não repetição — do único sacrifício do Calvário. Cristo não morre de novo; o mesmo sacrifício é tornado presente de forma incruenta. "Uma única oferta" (Hb 10,14).', explanationEn: 'The Catechism (§1367) teaches that the Mass is the sacramental re-presentation — not repetition — of the one sacrifice of Calvary. Christ does not die again; the same sacrifice is made present in an unbloody manner. "A single offering" (Heb 10:14).' },
];




// Perguntas devocionais/reflexivas para o quiz diário (~uma por dia do ano).
export const DAILY_QUESTIONS = [
  { id: 'dq-001', question: 'Quantas pessoas existem na Santíssima Trindade?', questionEn: 'How many persons exist in the Holy Trinity?', options: ['Uma', 'Duas', 'Três', 'Incontáveis'], optionsEn: ['One', 'Two', 'Three', 'Countless'], correct: 2, why: 'Um só Deus em três pessoas: Pai, Filho e Espírito Santo. As três são coeternas e coiguais em natureza divina.', whyEn: 'One God in three persons: Father, Son, and Holy Spirit. All three are co-eternal and co-equal in divine nature.' },
  { id: 'dq-002', question: 'Qual é o primeiro mandamento do Decálogo?', questionEn: 'What is the first commandment of the Decalogue?', options: ['Honra pai e mãe', 'Não matarás', 'Não terás outros deuses além de mim', 'Guardar o sábado'], optionsEn: ['Honor your father and mother', 'You shall not kill', 'You shall have no other gods before me', 'Keep the Sabbath'], correct: 2, why: 'O primeiro mandamento (Ex 20,3) coloca Deus no centro absoluto da vida. Tudo mais decorre daí: se Deus é primeiro, os outros mandamentos fazem sentido.', whyEn: 'The first commandment (Ex 20:3) places God at the absolute center of life. Everything else flows from it: if God is first, the other commandments make sense.' },
  { id: 'dq-003', question: 'Qual é a oração que Jesus ensinou diretamente aos discípulos?', questionEn: 'What is the prayer Jesus taught directly to his disciples?', options: ['Ave Maria', 'Pai-Nosso', 'Gloria Patri', 'Salve Regina'], optionsEn: ['Hail Mary', 'Our Father', 'Glory Be', 'Hail Holy Queen'], correct: 1, why: 'Mateus 6,9-13 e Lucas 11,2-4 registram Jesus ensinando o Pai-Nosso. É a oração cristã por excelência, chamada por Tertuliano de "resumo de todo o Evangelho".', whyEn: 'Matthew 6:9-13 and Luke 11:2-4 record Jesus teaching the Our Father. It is the Christian prayer par excellence, called by Tertullian "the summary of the whole Gospel".' },
  { id: 'dq-004', question: 'Quantos livros tem o Novo Testamento?', questionEn: 'How many books does the New Testament have?', options: ['24', '27', '29', '33'], optionsEn: ['24', '27', '29', '33'], correct: 1, why: 'O NT tem 27 livros: 4 Evangelhos, Atos, 13 cartas paulinas, Hebreus, 7 cartas católicas e Apocalipse. O número foi fixado pelos Concílios de Hipona (393) e Cartago (397).', whyEn: 'The NT has 27 books: 4 Gospels, Acts, 13 Pauline letters, Hebrews, 7 catholic letters, and Revelation. The number was fixed at the Councils of Hippo (393) and Carthage (397).' },
  { id: 'dq-005', question: 'Qual apóstolo negou Jesus três vezes antes do galo cantar?', questionEn: 'Which apostle denied Jesus three times before the rooster crowed?', options: ['Judas', 'Tomé', 'Pedro', 'João'], optionsEn: ['Judas', 'Thomas', 'Peter', 'John'], correct: 2, why: 'Pedro negou Jesus três vezes no pátio do sumo sacerdote (Lc 22,54-62). O galo cantou e Pedro "saiu e chorou amargamente". Depois da Ressurreição, Jesus o restaurou três vezes (Jo 21,15-17).', whyEn: 'Peter denied Jesus three times in the courtyard of the high priest (Lk 22:54-62). The rooster crowed and Peter "went out and wept bitterly". After the Resurrection, Jesus restored him three times (Jn 21:15-17).' },
  { id: 'dq-006', question: 'Quantos apóstolos escolheu Jesus?', questionEn: 'How many apostles did Jesus choose?', options: ['7', '10', '12', '70'], optionsEn: ['7', '10', '12', '70'], correct: 2, why: 'Jesus escolheu doze apóstolos (Mc 3,14-19), em correspondência com as doze tribos de Israel. O número 12 simboliza a fundação do novo povo de Deus.', whyEn: 'Jesus chose twelve apostles (Mk 3:14-19), corresponding to the twelve tribes of Israel. The number 12 symbolizes the foundation of the new people of God.' },
  { id: 'dq-007', question: 'Qual é o versículo mais curto da Bíblia (em português)?', questionEn: 'What is the shortest verse in the Bible (in English)?', options: ['"Deus é amor" (1 Jo 4,8)', '"Jesus chorou" (Jo 11,35)', '"Alegrai-vos sempre" (1 Ts 5,16)', '"Orai sem cessar" (1 Ts 5,17)'], optionsEn: ['"God is love" (1 Jn 4:8)', '"Jesus wept" (Jn 11:35)', '"Rejoice always" (1 Th 5:16)', '"Pray without ceasing" (1 Th 5:17)'], correct: 1, why: '"Jesus chorou" (Jo 11,35) é o versículo mais curto em muitas traduções. Aconteceu diante do túmulo de Lázaro, mostrando a humanidade e compaixão de Jesus.', whyEn: '"Jesus wept" (Jn 11:35) is the shortest verse in most translations. It happened before the tomb of Lazarus, showing Jesus\'s humanity and compassion.' },
  { id: 'dq-008', question: 'Qual é o primeiro livro da Bíblia?', questionEn: 'What is the first book of the Bible?', options: ['Êxodo', 'Salmos', 'Gênesis', 'Mateus'], optionsEn: ['Exodus', 'Psalms', 'Genesis', 'Matthew'], correct: 2, why: '"No princípio, Deus criou os céus e a terra" (Gn 1,1). Gênesis narra a criação, a queda, Noé, Abraão, Isaque, Jacó e José — as origens da salvação.', whyEn: '"In the beginning, God created the heavens and the earth" (Gn 1:1). Genesis recounts creation, the fall, Noah, Abraham, Isaac, Jacob, and Joseph — the origins of salvation.' },
  { id: 'dq-009', question: 'Em que cidade nasceu Jesus?', questionEn: 'In what city was Jesus born?', options: ['Nazaré', 'Jerusalém', 'Belém', 'Cafarnaum'], optionsEn: ['Nazareth', 'Jerusalem', 'Bethlehem', 'Capernaum'], correct: 2, why: 'Jesus nasceu em Belém da Judeia (Mt 2,1; Lc 2,4-7), cumprindo a profecia de Miquéias 5,1. Cresceu em Nazaré, por isso era chamado "o Nazareno".', whyEn: 'Jesus was born in Bethlehem of Judea (Mt 2:1; Lk 2:4-7), fulfilling the prophecy of Micah 5:1. He grew up in Nazareth, which is why he was called "the Nazarene".' },
  { id: 'dq-010', question: 'Quem batizou Jesus?', questionEn: 'Who baptized Jesus?', options: ['Pedro', 'João Batista', 'Um anjo', 'José'], optionsEn: ['Peter', 'John the Baptist', 'An angel', 'Joseph'], correct: 1, why: 'João Batista batizou Jesus no rio Jordão (Mt 3,13-17). João hesitou, dizendo precisar ser batizado por Jesus. Ao ser batizado, o Espírito desceu como pomba e o Pai disse: "Este é o meu Filho amado".', whyEn: 'John the Baptist baptized Jesus in the Jordan River (Mt 3:13-17). John hesitated, saying he needed to be baptized by Jesus. At the baptism, the Spirit descended as a dove and the Father said: "This is my beloved Son".' },
  { id: 'dq-011', question: 'Qual o significado do nome "Jesus" em hebraico?', questionEn: 'What is the meaning of the name "Jesus" in Hebrew?', options: ['Luz do mundo', 'Filho de Deus', 'Deus salva', 'Rei dos reis'], optionsEn: ['Light of the world', 'Son of God', 'God saves', 'King of kings'], correct: 2, why: '"Jesus" vem do hebraico "Yeshua" (Yahweh salva). O anjo disse a José: "darás a ele o nome de Jesus, pois ele salvará o seu povo dos seus pecados" (Mt 1,21).', whyEn: '"Jesus" comes from the Hebrew "Yeshua" (God saves). The angel told Joseph: "you shall call his name Jesus, for he will save his people from their sins" (Mt 1:21).' },
  { id: 'dq-012', question: 'Quantos dias ficou Jesus no deserto tentado pelo diabo?', questionEn: 'How many days did Jesus spend in the desert being tempted by the devil?', options: ['3 dias', '7 dias', '30 dias', '40 dias'], optionsEn: ['3 days', '7 days', '30 days', '40 days'], correct: 3, why: '40 dias (Mt 4,2; Lc 4,2), em paralelo com os 40 anos de Israel no deserto e os 40 dias de Moisés no Sinai. O número 40 na Bíblia indica período de provação e purificação.', whyEn: '40 days (Mt 4:2; Lk 4:2), in parallel with Israel\'s 40 years in the desert and Moses\'s 40 days on Sinai. The number 40 in the Bible indicates a period of trial and purification.' },
  { id: 'dq-013', question: 'Qual foi o primeiro milagre de Jesus registrado no Evangelho de João?', questionEn: 'What was Jesus\'s first miracle recorded in the Gospel of John?', options: ['Curar um cego', 'Multiplicar pães', 'Transformar água em vinho', 'Ressuscitar Lázaro'], optionsEn: ['Healing a blind man', 'Multiplying loaves', 'Turning water into wine', 'Raising Lazarus'], correct: 2, why: 'João 2,1-11: nas bodas de Caná, Jesus transformou água em vinho a pedido de Maria. João chama isso de "o primeiro dos seus sinais", revelando sua glória.', whyEn: 'John 2:1-11: at the wedding in Cana, Jesus turned water into wine at Mary\'s request. John calls it "the first of his signs", revealing his glory.' },
  { id: 'dq-014', question: 'Qual apóstolo traiu Jesus por trinta moedas de prata?', questionEn: 'Which apostle betrayed Jesus for thirty pieces of silver?', options: ['Simão Zelote', 'Tomé', 'Judas Iscariotes', 'Bartolomeu'], optionsEn: ['Simon the Zealot', 'Thomas', 'Judas Iscariot', 'Bartholomew'], correct: 2, why: 'Judas Iscariotes combinou com os chefes dos sacerdotes entregar Jesus por 30 moedas de prata (Mt 26,14-16), cumprindo Zacarias 11,12. Depois se arrependeu e devolveu o dinheiro, mas foi tarde demais.', whyEn: 'Judas Iscariot arranged with the chief priests to hand Jesus over for 30 pieces of silver (Mt 26:14-16), fulfilling Zechariah 11:12. He later repented and returned the money, but it was too late.' },
  { id: 'dq-015', question: 'Em qual dia da semana Jesus ressuscitou?', questionEn: 'On which day of the week did Jesus rise?', options: ['Sexta-feira', 'Sábado', 'Domingo', 'Segunda-feira'], optionsEn: ['Friday', 'Saturday', 'Sunday', 'Monday'], correct: 2, why: 'Jesus ressuscitou "no primeiro dia da semana" (Jo 20,1; Mc 16,2) — o domingo. Por isso os cristãos celebram a Eucaristia aos domingos, "o Dia do Senhor" (Ap 1,10).', whyEn: 'Jesus rose "on the first day of the week" (Jn 20:1; Mk 16:2) — Sunday. This is why Christians celebrate the Eucharist on Sundays, "the Lord\'s Day" (Rev 1:10).' },
  { id: 'dq-016', question: 'Quantos dias após a Ressurreição ocorreu a Ascensão de Jesus?', questionEn: 'How many days after the Resurrection did the Ascension of Jesus occur?', options: ['3 dias', '7 dias', '40 dias', '50 dias'], optionsEn: ['3 days', '7 days', '40 days', '50 days'], correct: 2, why: 'Atos 1,3: Jesus apareceu aos apóstolos durante 40 dias após a Ressurreição, "falando do Reino de Deus". No quadragésimo dia, ascendeu ao céu diante deles no Monte das Oliveiras.', whyEn: 'Acts 1:3: Jesus appeared to the apostles for 40 days after the Resurrection, "speaking of the kingdom of God". On the fortieth day, he ascended to heaven before them on the Mount of Olives.' },
  { id: 'dq-017', question: 'Quantos dias após a Ascensão ocorreu Pentecostes?', questionEn: 'How many days after the Ascension did Pentecost occur?', options: ['3 dias', '7 dias', '10 dias', '50 dias total desde a Páscoa'], optionsEn: ['3 days', '7 days', '10 days', '50 days total from Easter'], correct: 3, why: '"Pentecostes" vem do grego "cinquenta". Ocorre 50 dias após a Páscoa (10 dias após a Ascensão). O Espírito Santo desceu sobre Maria e os apóstolos em Jerusalém (At 2,1-4).', whyEn: '"Pentecost" comes from the Greek "fifty". It occurs 50 days after Easter (10 days after the Ascension). The Holy Spirit descended upon Mary and the apostles in Jerusalem (Acts 2:1-4).' },
  { id: 'dq-018', question: 'Qual apóstolo é chamado de "o amado" no Evangelho de João?', questionEn: 'Which apostle is called "the beloved" in the Gospel of John?', options: ['Pedro', 'Paulo', 'João', 'Tiago'], optionsEn: ['Peter', 'Paul', 'John', 'James'], correct: 2, why: 'O "discípulo amado" aparece em João 13, 19, 20 e 21. Tradição cristã o identifica como João, filho de Zebedeu. Foi o único apóstolo presente na Crucificação e recebeu Maria aos seus cuidados.', whyEn: 'The "beloved disciple" appears in John 13, 19, 20, and 21. Christian tradition identifies him as John, son of Zebedee. He was the only apostle present at the Crucifixion and received Mary into his care.' },
  { id: 'dq-019', question: 'Qual é o maior mandamento, segundo Jesus?', questionEn: 'What is the greatest commandment, according to Jesus?', options: ['Não matarás', 'Amar a Deus com todo o coração, alma e mente', 'Guardar o sábado', 'Não cobiçarás'], optionsEn: ['You shall not kill', 'Love God with all your heart, soul, and mind', 'Keep the Sabbath', 'You shall not covet'], correct: 1, why: 'Mateus 22,37-39: Jesus cita Deuteronômio 6,5 como o maior mandamento, e acrescenta o segundo (Lv 19,18): "amarás o teu próximo como a ti mesmo". "Destes dois mandamentos dependem toda a Lei e os Profetas."', whyEn: 'Matthew 22:37-39: Jesus quotes Deuteronomy 6:5 as the greatest commandment, and adds the second (Lv 19:18): "you shall love your neighbor as yourself". "On these two commandments hang all the Law and the Prophets."' },
  { id: 'dq-020', question: 'Qual é o fruto mais importante do Espírito Santo, segundo São Paulo?', questionEn: 'What is the greatest fruit of the Holy Spirit, according to St. Paul?', options: ['Alegria', 'Paz', 'Amor', 'Paciência'], optionsEn: ['Joy', 'Peace', 'Love', 'Patience'], correct: 2, why: 'Gálatas 5,22-23 lista os frutos do Espírito. Paulo em 1 Coríntios 13 declara que o amor é o maior: "Se eu falar as línguas dos homens e dos anjos, mas não tiver amor, sou como o bronze que soa".', whyEn: 'Galatians 5:22-23 lists the fruits of the Spirit. Paul in 1 Corinthians 13 declares love the greatest: "If I speak in the tongues of men and of angels, but have not love, I am a noisy gong".' },
  { id: 'dq-021', question: 'Quantas Bem-Aventuranças Jesus proclamou no Sermão da Montanha?', questionEn: 'How many Beatitudes did Jesus proclaim in the Sermon on the Mount?', options: ['5', '7', '8', '10'], optionsEn: ['5', '7', '8', '10'], correct: 2, why: 'Mateus 5,3-10 lista 8 Bem-Aventuranças, cada uma começando com "Bem-aventurados os...". Lucas 6,20-23 registra 4. As oito de Mateus são o texto clássico da tradição cristã.', whyEn: 'Matthew 5:3-10 lists 8 Beatitudes, each beginning "Blessed are the...". Luke 6:20-23 records 4. Matthew\'s eight are the classical text in Christian tradition.' },
  { id: 'dq-022', question: 'O que é a "graça santificante"?', questionEn: 'What is "sanctifying grace"?', options: ['Um sentimento de paz interior', 'A participação na vida divina que nos torna agradáveis a Deus e filhos Seus', 'A capacidade de fazer milagres', 'O perdão dos pecados veniais'], optionsEn: ['A feeling of inner peace', 'Participation in divine life that makes us pleasing to God and His children', 'The ability to work miracles', 'The forgiveness of venial sins'], correct: 1, why: 'A graça santificante é a presença habitual de Deus na alma (Jo 14,23). É perdida pelo pecado mortal e restaurada pela Confissão. Ela nos faz "participantes da natureza divina" (2 Pd 1,4).', whyEn: 'Sanctifying grace is the habitual presence of God in the soul (Jn 14:23). It is lost through mortal sin and restored through Confession. It makes us "partakers of the divine nature" (2 Pt 1:4).' },
  { id: 'dq-023', question: 'Qual é a única petição do Pai-Nosso que Jesus comentou explicitamente?', questionEn: 'Which is the only petition of the Our Father that Jesus explicitly commented on?', options: ['O pão nosso de cada dia', 'O perdão das ofensas', 'A libertação do mal', 'A vinda do Reino'], optionsEn: ['Our daily bread', 'Forgiveness of offenses', 'Deliverance from evil', 'The coming of the Kingdom'], correct: 1, why: 'Após o Pai-Nosso, Jesus comenta apenas: "Se perdoardes as ofensas aos homens, o Pai celestial também vos perdoará; mas se não perdoardes, o Pai também não vos perdoará" (Mt 6,14-15).', whyEn: 'After the Our Father, Jesus comments only: "For if you forgive others their trespasses, your heavenly Father will also forgive you; but if you do not forgive others, neither will your Father forgive your trespasses" (Mt 6:14-15).' },
  { id: 'dq-024', question: 'Qual é o livro mais longo da Bíblia?', questionEn: 'What is the longest book of the Bible?', options: ['Gênesis', 'Isaías', 'Salmos', 'Jeremias'], optionsEn: ['Genesis', 'Isaiah', 'Psalms', 'Jeremiah'], correct: 2, why: 'O livro dos Salmos é o mais longo da Bíblia (150 salmos, ~43.000 palavras em hebraico). É o livro mais citado no Novo Testamento. Jesus citou os Salmos repetidamente, inclusive da Cruz (Sl 22).', whyEn: 'The Book of Psalms is the longest in the Bible (150 psalms, ~43,000 words in Hebrew). It is the most quoted book in the New Testament. Jesus quoted the Psalms repeatedly, including from the Cross (Ps 22).' },
  { id: 'dq-025', question: 'Qual foi a profissão de São Paulo antes de se converter?', questionEn: 'What was St. Paul\'s profession before his conversion?', options: ['Pescador', 'Carpinteiro', 'Fariseu e perseguidor dos cristãos', 'Publicano'], optionsEn: ['Fisherman', 'Carpenter', 'Pharisee and persecutor of Christians', 'Tax collector'], correct: 2, why: 'Paulo (Saulo de Tarso) era fariseu, discípulo de Gamaliel, e participou ativamente da perseguição aos cristãos, incluindo a morte de Estêvão (At 7,58; Fl 3,5). Foi convertido na estrada de Damasco (At 9).', whyEn: 'Paul (Saul of Tarsus) was a Pharisee, disciple of Gamaliel, and actively participated in the persecution of Christians, including the death of Stephen (Acts 7:58; Phil 3:5). He was converted on the road to Damascus (Acts 9).' },
  { id: 'dq-026', question: 'Qual saudação o anjo Gabriel usou ao aparecer a Maria?', questionEn: 'What greeting did the angel Gabriel use when appearing to Mary?', options: ['Shalom, Maria', 'Alegra-te, cheia de graça', 'Louvado seja o Senhor', 'Paz a ti'], optionsEn: ['Shalom, Mary', 'Hail, full of grace', 'Praise be to the Lord', 'Peace to you'], correct: 1, why: 'Lucas 1,28: "Alegra-te (chaire), cheia de graça (kecharitomene), o Senhor está contigo". O grego "kecharitomene" (particípio perfeito passivo) indica uma graça permanente e completa — base do dogma da Imaculada Conceição.', whyEn: 'Luke 1:28: "Hail (chaire), full of grace (kecharitomene), the Lord is with you". The Greek "kecharitomene" (perfect passive participle) indicates a permanent and complete grace — the basis for the dogma of the Immaculate Conception.' },
  { id: 'dq-027', question: 'Qual nome deu Isabel a Jesus antes de nascer?', questionEn: 'What name did Elizabeth give Jesus before he was born?', options: ['Messias', 'Senhor', 'Emanuel', 'Filho do Altíssimo'], optionsEn: ['Messiah', 'Lord', 'Emmanuel', 'Son of the Most High'], correct: 1, why: 'Lucas 1,43: ao visitar Isabel, o bebê (João) saltou no ventre e Isabel exclamou: "Como é possível que a Mãe de meu Senhor venha a mim?". É a primeira proclamação pós-encarnação de Jesus como "Senhor".', whyEn: 'Luke 1:43: when Mary visited Elizabeth, the baby (John) leaped in the womb and Elizabeth exclaimed: "And why is this granted to me that the mother of my Lord should come to me?" It is the first post-Incarnation proclamation of Jesus as "Lord".' },
  { id: 'dq-028', question: 'Qual é o sacramento que imprime caráter indelével na alma e só pode ser recebido uma vez?', questionEn: 'Which sacrament imprints an indelible character on the soul and can be received only once?', options: ['Eucaristia', 'Confissão', 'Batismo', 'Matrimônio'], optionsEn: ['Eucharist', 'Confession', 'Baptism', 'Matrimony'], correct: 2, why: 'Três sacramentos imprimem caráter indelével (impossível de repetir): Batismo, Confirmação e Ordem Sagrada. Por isso não podem ser recebidos mais de uma vez. O Catecismo (§1272) chama o Batismo de "selo espiritual".', whyEn: 'Three sacraments imprint an indelible character (impossible to repeat): Baptism, Confirmation, and Holy Orders. That is why they cannot be received more than once. The Catechism (§1272) calls Baptism a "spiritual seal".' },
  { id: 'dq-029', question: 'Qual é a oração mais repetida diariamente por católicos em todo o mundo?', questionEn: 'What is the prayer most repeated daily by Catholics worldwide?', options: ['Pai-Nosso', 'Ave Maria', 'Credo', 'Salve Regina'], optionsEn: ['Our Father', 'Hail Mary', 'Creed', 'Hail Holy Queen'], correct: 1, why: 'A Ave Maria (composta do cumprimento do anjo Lc 1,28, da saudação de Isabel Lc 1,42 e da petição medieval) é rezada milhões de vezes por dia no Rosário e em outras devoções.', whyEn: 'The Hail Mary (composed of the angel\'s greeting Lk 1:28, Elizabeth\'s salutation Lk 1:42, and a medieval petition) is prayed millions of times daily in the Rosary and other devotions.' },
  { id: 'dq-030', question: 'O que significa "Amen" ao final das orações?', questionEn: 'What does "Amen" at the end of prayers mean?', options: ['Obrigado', 'Fim da oração', 'Assim seja / Verdadeiramente', 'Louvor a Deus'], optionsEn: ['Thank you', 'End of prayer', 'So be it / Truly', 'Praise to God'], correct: 2, why: '"Amém" vem do hebraico "amen" (firme, verdadeiro). Na Bíblia indica ratificação e confiança. Jesus usava "Amém, amém, digo-vos" (em João) para marcar declarações solenes. No final das orações, expressa acordo e confiança.', whyEn: '"Amen" comes from the Hebrew "amen" (firm, true). In the Bible it indicates ratification and trust. Jesus used "Amen, amen, I say to you" (in John) to mark solemn declarations. At the end of prayers it expresses agreement and trust.' },
  { id: 'dq-031', question: 'Quais são as três virtudes teologais?', questionEn: 'What are the three theological virtues?', options: ['Fé, esperança e caridade', 'Prudência, justiça e fortaleza', 'Humildade, obediência e pobreza', 'Oração, jejum e esmola'], optionsEn: ['Faith, hope, and charity', 'Prudence, justice, and fortitude', 'Humility, obedience, and poverty', 'Prayer, fasting, and almsgiving'], correct: 0, why: '1 Coríntios 13,13: "Agora permanecem estas três coisas: a fé, a esperança e o amor; a maior delas é o amor". São chamadas "teologais" porque têm Deus como origem, motivo e objeto direto.', whyEn: '1 Corinthians 13:13: "So now faith, hope, and love abide, these three; but the greatest of these is love". They are called "theological" because God is their origin, motive, and direct object.' },
  { id: 'dq-032', question: 'Quais são as quatro virtudes cardeais?', questionEn: 'What are the four cardinal virtues?', options: ['Fé, esperança, caridade e paciência', 'Prudência, justiça, fortaleza e temperança', 'Humildade, obediência, castidade e pobreza', 'Oração, jejum, esmola e penitência'], optionsEn: ['Faith, hope, charity, and patience', 'Prudence, justice, fortitude, and temperance', 'Humility, obedience, chastity, and poverty', 'Prayer, fasting, almsgiving, and penance'], correct: 1, why: 'As quatro virtudes cardeais vêm de Platão e foram adotadas por Tomás de Aquino. "Cardinal" vem do latim "cardo" (dobradiça) — todas as outras virtudes giram em torno delas. Estão em Sabedoria 8,7.', whyEn: 'The four cardinal virtues come from Plato and were adopted by Thomas Aquinas. "Cardinal" comes from the Latin "cardo" (hinge) — all other virtues revolve around them. They appear in Wisdom 8:7.' },
  { id: 'dq-033', question: 'Quais são os sete pecados capitais?', questionEn: 'What are the seven capital sins?', options: ['Orgulho, inveja, ira, avareza, preguiça, gula, luxúria', 'Mentira, roubo, assassinato, adultério, idolatria, blasfêmia, desobediência', 'Heresia, apostasia, cisma, sacrilégio, impiedade, superstição, magia', 'Soberba, acídia, timidez, fraqueza, indiferença, medo, desconfiança'], optionsEn: ['Pride, envy, anger, greed, sloth, gluttony, lust', 'Lying, theft, murder, adultery, idolatry, blasphemy, disobedience', 'Heresy, apostasy, schism, sacrilege, impiety, superstition, magic', 'Pride, acedia, timidity, weakness, indifference, fear, distrust'], correct: 0, why: 'Os sete pecados capitais (Gregório Magno, séc. VI) são raízes dos outros pecados: soberba, avareza, luxúria, ira, gula, inveja e preguiça/acídia. "Capital" vem de "caput" (cabeça) — são a fonte.', whyEn: 'The seven capital sins (Gregory the Great, 6th century) are roots of other sins: pride, greed, lust, anger, gluttony, envy, and sloth/acedia. "Capital" comes from "caput" (head) — they are the source.' },
  { id: 'dq-034', question: 'Quem escreveu o livro dos Atos dos Apóstolos?', questionEn: 'Who wrote the Book of Acts?', options: ['Pedro', 'Paulo', 'Lucas', 'João'], optionsEn: ['Peter', 'Paul', 'Luke', 'John'], correct: 2, why: 'Atos foi escrito pelo mesmo autor do Terceiro Evangelho — Lucas, médico e companheiro de Paulo (Cl 4,14). Os dois livros formam uma obra em dois volumes dedicada a "Teófilo".', whyEn: 'Acts was written by the same author as the Third Gospel — Luke, physician and companion of Paul (Col 4:14). The two books form a two-volume work dedicated to "Theophilus".' },
  { id: 'dq-035', question: 'O que é a "lectio divina"?', questionEn: 'What is "lectio divina"?', options: ['A leitura do cânon litúrgico pelo padre', 'Uma prática de leitura orante da Escritura em quatro etapas', 'O estudo crítico histórico da Bíblia', 'A recitação do breviário'], optionsEn: ['The liturgical canon reading by the priest', 'A prayerful reading of Scripture in four steps', 'The historical-critical study of the Bible', 'The recitation of the Breviary'], correct: 1, why: 'Lectio divina (leitura divina) é uma prática monástica com quatro momentos: lectio (ler), meditatio (meditar), oratio (orar) e contemplatio (contemplar). Popularizada por Guigo II (séc. XII) e recomendada pelo Vaticano II.', whyEn: 'Lectio divina (divine reading) is a monastic practice with four moments: lectio (read), meditatio (meditate), oratio (pray), and contemplatio (contemplate). Popularized by Guigo II (12th century) and recommended by Vatican II.' },
  { id: 'dq-036', question: 'Qual é o sacramento que só bispos podem administrar ordinariamente?', questionEn: 'Which sacrament can ordinarily only bishops administer?', options: ['Batismo', 'Eucaristia', 'Confirmação', 'Matrimônio'], optionsEn: ['Baptism', 'Eucharist', 'Confirmation', 'Matrimony'], correct: 2, why: 'Ordinariamente, o bispo é o ministro da Confirmação. Por motivo grave, ele pode delegar a um padre (CIC §882). No Oriente católico, o padre que batiza também confirma imediatamente.', whyEn: 'Ordinarily, the bishop is the minister of Confirmation. For serious reason, he can delegate to a priest (CIC §882). In the Eastern Catholic Church, the priest who baptizes also confirms immediately.' },
  { id: 'dq-037', question: 'Qual é o livro do Antigo Testamento que narra a história de Rute?', questionEn: 'Which Old Testament book tells the story of Ruth?', options: ['Juízes', 'Rute', 'Ester', 'Tobias'], optionsEn: ['Judges', 'Ruth', 'Esther', 'Tobit'], correct: 1, why: 'O Livro de Rute narra a fidelidade de Rute, moabita, à sua sogra Noemi: "Onde você for, eu irei; onde você ficar, eu ficarei" (Rt 1,16). Rute é ancestral de Davi e de Jesus.', whyEn: 'The Book of Ruth recounts the faithfulness of Ruth, a Moabite, to her mother-in-law Naomi: "Where you go I will go; where you stay I will stay" (Rt 1:16). Ruth is an ancestor of David and of Jesus.' },
  { id: 'dq-038', question: 'Quem escreveu a maioria das cartas do Novo Testamento?', questionEn: 'Who wrote most of the letters in the New Testament?', options: ['Pedro', 'João', 'Paulo', 'Tiago'], optionsEn: ['Peter', 'John', 'Paul', 'James'], correct: 2, why: 'Paulo escreveu ao menos 13 cartas (Romanos até Filemom), possivelmente 14 incluindo Hebreus. Representam mais da metade do NT em número de livros e são a base da teologia cristã sistemática.', whyEn: 'Paul wrote at least 13 letters (Romans through Philemon), possibly 14 including Hebrews. They represent more than half the NT in number of books and are the basis of systematic Christian theology.' },
  { id: 'dq-039', question: 'O que celebra a Festa de Corpus Christi?', questionEn: 'What does the Feast of Corpus Christi celebrate?', options: ['A Ressurreição de Cristo', 'A instituição da Eucaristia e a presença real de Cristo no sacramento', 'O Batismo de Jesus', 'A Ascensão ao Céu'], optionsEn: ['The Resurrection of Christ', 'The institution of the Eucharist and the real presence of Christ in the sacrament', 'The Baptism of Jesus', 'The Ascension to Heaven'], correct: 1, why: 'Corpus Christi (Corpo de Cristo) foi instituída em 1264 pelo Papa Urbano IV. Celebra a presença real de Jesus na Eucaristia com procissões, adoração e os hinos de Tomás de Aquino (Tantum Ergo, Pange Lingua).', whyEn: 'Corpus Christi (Body of Christ) was instituted in 1264 by Pope Urban IV. It celebrates the real presence of Jesus in the Eucharist with processions, adoration, and the hymns of Thomas Aquinas (Tantum Ergo, Pange Lingua).' },
  { id: 'dq-040', question: 'Qual é a promessa central do Evangelho (kerygma)?', questionEn: 'What is the central promise of the Gospel (kerygma)?', options: ['Prosperidade material para os crentes', 'Salvação e vida eterna pela fé em Jesus Cristo morto e ressuscitado', 'Paz política entre as nações', 'Saúde perfeita e ausência de sofrimento'], optionsEn: ['Material prosperity for believers', 'Salvation and eternal life through faith in Jesus Christ, dead and risen', 'Political peace between nations', 'Perfect health and absence of suffering'], correct: 1, why: 'O kerygma primitivo (At 2,22-36; 1 Cor 15,3-5): Jesus morreu pelos nossos pecados, foi sepultado, ressuscitou ao terceiro dia e apareceu. Quem crê e se batiza é salvo (Mc 16,16).', whyEn: 'The primitive kerygma (Acts 2:22-36; 1 Cor 15:3-5): Jesus died for our sins, was buried, rose on the third day, and appeared. Whoever believes and is baptized will be saved (Mk 16:16).' },
  { id: 'dq-041', question: 'O que é o "Fiat" de Maria?', questionEn: 'What is Mary\'s "Fiat"?', options: ['O nome de seu pai', 'Seu consentimento à Encarnação: "Faça-se em mim segundo a tua palavra"', 'Uma oração de intercessão', 'Sua saudação a Isabel'], optionsEn: ['The name of her father', 'Her consent to the Incarnation: "Be it done to me according to your word"', 'A prayer of intercession', 'Her greeting to Elizabeth'], correct: 1, why: 'Lucas 1,38: "Eis aqui a serva do Senhor; faça-se em mim segundo a tua palavra." O "Fiat" (seja feito) de Maria é o sim que torna possível a Encarnação. Contrasta com o "não" de Eva.', whyEn: 'Luke 1:38: "Behold the handmaid of the Lord; be it done to me according to your word." Mary\'s "Fiat" (let it be done) is the yes that makes the Incarnation possible. It contrasts with Eve\'s "no".' },
  { id: 'dq-042', question: 'O que celebra o Domingo de Ramos?', questionEn: 'What does Palm Sunday celebrate?', options: ['A Última Ceia de Jesus', 'A entrada triunfal de Jesus em Jerusalém', 'A Ressurreição de Jesus', 'O Batismo de Jesus'], optionsEn: ['The Last Supper of Jesus', 'The triumphal entry of Jesus into Jerusalem', 'The Resurrection of Jesus', 'The Baptism of Jesus'], correct: 1, why: 'O Domingo de Ramos abre a Semana Santa. Jesus entrou em Jerusalém montado num jumento, cumprindo Zacarias 9,9. A multidão o aclamava com ramos e "Hosana ao Filho de Davi" (Mt 21,9).', whyEn: 'Palm Sunday opens Holy Week. Jesus entered Jerusalem riding a donkey, fulfilling Zechariah 9:9. The crowd hailed him with branches and "Hosanna to the Son of David" (Mt 21:9).' },
  { id: 'dq-043', question: 'Qual é o maior martírio da história do cristianismo primitivo?', questionEn: 'Who was the first martyr (protomartyr) of Christianity?', options: ['São João Batista', 'São Estêvão', 'São Pedro', 'São Paulo'], optionsEn: ['St. John the Baptist', 'St. Stephen', 'St. Peter', 'St. Paul'], correct: 1, why: 'Estêvão, diácono, foi apedrejado pela sanidade judaica (At 6-7) e é o primeiro mártir cristão (proto-mártir). Suas últimas palavras: "Senhor Jesus, recebe o meu espírito... não lhes imputes este pecado" (At 7,59-60).', whyEn: 'Stephen, a deacon, was stoned by the Jewish council (Acts 6-7) and is the first Christian martyr (proto-martyr). His last words: "Lord Jesus, receive my spirit... do not hold this sin against them" (Acts 7:59-60).' },
  { id: 'dq-044', question: 'Qual é o pecado que Jesus disse não ter perdão?', questionEn: 'What is the sin that Jesus said has no forgiveness?', options: ['Assassinato', 'Adultério', 'Blasfêmia contra o Espírito Santo', 'Apostasia'], optionsEn: ['Murder', 'Adultery', 'Blasphemy against the Holy Spirit', 'Apostasy'], correct: 2, why: 'Mateus 12,31-32: "qualquer pecado e blasfêmia serão perdoados... mas a blasfêmia contra o Espírito não será perdoada." Os teólogos interpretam como a recusa definitiva e obstinada da graça divina.', whyEn: 'Matthew 12:31-32: "every sin and blasphemy will be forgiven... but the blasphemy against the Spirit will not be forgiven." Theologians interpret this as the definitive, obstinate refusal of divine grace.' },
  { id: 'dq-045', question: 'O que é a "Tradição Apostólica"?', questionEn: 'What is the "Apostolic Tradition"?', options: ['Os escritos dos Padres da Igreja', 'O ensinamento transmitido pelos apóstolos, vivo na Igreja, distinto mas não separado da Escritura', 'As regras de disciplina eclesiástica', 'Os costumes litúrgicos medievais'], optionsEn: ['The writings of the Church Fathers', 'The teaching transmitted by the apostles, alive in the Church, distinct but not separate from Scripture', 'The rules of ecclesiastical discipline', 'Medieval liturgical customs'], correct: 1, why: '"Dei Verbum" §9 (Vaticano II): Escritura e Tradição formam "um único depósito sagrado da Palavra de Deus". A Tradição Apostólica transmite tudo o que Cristo revelou, incluindo o que não está escrito (2 Ts 2,15).', whyEn: '"Dei Verbum" §9 (Vatican II): Scripture and Tradition form "one sacred deposit of the Word of God". The Apostolic Tradition transmits everything Christ revealed, including what is not written (2 Th 2:15).' },
  { id: 'dq-046', question: 'Qual profeta do AT profetizou "Uma virgem conceberá e dará à luz um filho, e será chamado Emanuel"?', questionEn: 'Which OT prophet foretold "A virgin will conceive and give birth to a son, and will call him Immanuel"?', options: ['Jeremias', 'Ezequiel', 'Isaías', 'Miquéias'], optionsEn: ['Jeremiah', 'Ezekiel', 'Isaiah', 'Micah'], correct: 2, why: 'Isaías 7,14, citado em Mateus 1,23. O hebraico "almah" (jovem/virgem) foi traduzido na Septuaginta como "parthenos" (virgem), confirmando a interpretação messiânica.', whyEn: 'Isaiah 7:14, quoted in Matthew 1:23. The Hebrew "almah" (young woman/virgin) was translated in the Septuagint as "parthenos" (virgin), confirming the messianic interpretation.' },
  { id: 'dq-047', question: 'Qual é o significado de "Pentecostes" para os judeus antes de Cristo?', questionEn: 'What is the meaning of "Pentecost" for Jews before Christ?', options: ['Festa da colheita de trigo e da entrega da Lei no Sinai', 'Festa da Páscoa', 'Início do ano novo judaico', 'Dia do Grande Perdão'], optionsEn: ['Feast of wheat harvest and giving of the Law at Sinai', 'Passover feast', 'Start of the Jewish new year', 'Day of Great Forgiveness'], correct: 0, why: 'Pentecostes (Shavuot) era a festa das primícias do trigo, 50 dias após a Páscoa, e celebrava a entrega da Torá no Sinai. O NT mostra o Espírito Santo sendo "entregue" no Pentecostes cristão — nova Lei inscrita no coração.', whyEn: 'Pentecost (Shavuot) was the feast of wheat firstfruits, 50 days after Passover, celebrating the giving of the Torah at Sinai. The NT shows the Holy Spirit being "given" at Christian Pentecost — new Law written in the heart.' },
  { id: 'dq-048', question: 'Qual é a definição clássica de oração dada por Santa Teresa de Ávila?', questionEn: 'What is the classical definition of prayer given by St. Teresa of Ávila?', options: ['Falar com Deus repetindo fórmulas sagradas', 'Conversa íntima de amizade com Aquele que sabemos que nos ama', 'A leitura atenta da Sagrada Escritura', 'O cumprimento dos ritos litúrgicos com devoção'], optionsEn: ['Speaking to God by repeating sacred formulas', 'Intimate friendly conversation with Him whom we know loves us', 'The attentive reading of Sacred Scripture', 'The fulfillment of liturgical rites with devotion'], correct: 1, why: 'Teresa de Ávila (Vida, cap. 8): "A oração mental não é senão uma conversa íntima de amizade com Aquele que sabemos que nos ama." Define a oração como relação pessoal, não apenas ato externo.', whyEn: 'Teresa of Ávila (Life, ch. 8): "Mental prayer is nothing else than an intimate sharing between friends; it means taking time frequently to be alone with Him who we know loves us." It defines prayer as a personal relationship, not just an external act.' },
  { id: 'dq-049', question: 'Qual é o salmo mais conhecido e rezado na liturgia das horas?', questionEn: 'What is the most known and prayed psalm in the Liturgy of the Hours?', options: ['Salmo 1', 'Salmo 22', 'Salmo 23', 'Salmo 150'], optionsEn: ['Psalm 1', 'Psalm 22', 'Psalm 23', 'Psalm 150'], correct: 2, why: 'O Salmo 23 ("O Senhor é meu pastor") é o mais amado e memorizado. Combina intimidade ("nada me faltará") com confiança diante da morte ("mesmo que eu caminhe pelo vale da sombra da morte").', whyEn: 'Psalm 23 ("The Lord is my shepherd") is the most beloved and memorized. It combines intimacy ("I shall not want") with confidence before death ("even though I walk through the valley of the shadow of death").' },
  { id: 'dq-050', question: 'O que é o "Magnificat"?', questionEn: 'What is the "Magnificat"?', options: ['Um decreto papal', 'O cântico de louvor de Maria ao visitar Isabel (Lc 1,46-55)', 'A oração de consagração da Missa', 'Um hino gregoriano medieval'], optionsEn: ['A papal decree', 'Mary\'s canticle of praise when visiting Elizabeth (Lk 1:46-55)', 'The prayer of consecration of the Mass', 'A medieval Gregorian hymn'], correct: 1, why: 'Lucas 1,46-55: "Minha alma glorifica o Senhor..." Maria celebra a misericórdia de Deus para com os humildes. O Magnificat é rezado diariamente nas Vésperas (Liturgia das Horas) da Igreja.', whyEn: 'Luke 1:46-55: "My soul magnifies the Lord..." Mary celebrates God\'s mercy toward the humble. The Magnificat is prayed daily at Vespers (Liturgy of the Hours) in the Church.' },
  { id: 'dq-051', question: 'Qual é a mensagem central da Carta de Tiago?', questionEn: 'What is the central message of the Letter of James?', options: ['A justificação pela sola fide', 'A fé sem obras é morta', 'A ressurreição dos mortos', 'O papel do Espírito Santo'], optionsEn: ['Justification by faith alone', 'Faith without works is dead', 'The resurrection of the dead', 'The role of the Holy Spirit'], correct: 1, why: 'Tiago 2,17: "Assim também a fé, se não tiver obras, é morta em si mesma". Tiago combate um quietismo que separa fé de vida moral. Paulo e Tiago se complementam: Paulo combate obras sem fé; Tiago combate fé sem obras.', whyEn: 'James 2:17: "So also faith by itself, if it does not have works, is dead." James combats a quietism that separates faith from moral life. Paul and James complement each other: Paul combats works without faith; James combats faith without works.' },
  { id: 'dq-052', question: 'O que Jesus quis dizer com "Eu sou o caminho, a verdade e a vida" (Jo 14,6)?', questionEn: 'What did Jesus mean by "I am the way, the truth, and the life" (Jn 14:6)?', options: ['Que seguir uma regra moral leva a Deus', 'Que ele é o único mediador entre Deus e os homens, a única via de salvação', 'Que a fé cristã é superior às outras religiões culturalmente', 'Que a Bíblia é o único caminho para conhecer Deus'], optionsEn: ['That following a moral rule leads to God', 'That he is the sole mediator between God and men, the only way of salvation', 'That Christianity is culturally superior to other religions', 'That the Bible is the only way to know God'], correct: 1, why: 'Jesus afirma ser o único mediador (1 Tm 2,5) e a única porta (Jo 10,9). "Caminho" (acesso ao Pai), "verdade" (Ele mesmo é a verdade divina encarnada) e "vida" (oferece a vida divina). Contexto: consolar os apóstolos antes da Paixão.', whyEn: 'Jesus affirms himself as the sole mediator (1 Tm 2:5) and the only gate (Jn 10:9). "Way" (access to the Father), "truth" (He is the incarnate divine truth), and "life" (He offers divine life). Context: consoling the apostles before the Passion.' },
  { id: 'dq-053', question: 'Qual é a última palavra de Jesus na Cruz, segundo o Evangelho de João?', questionEn: 'What is the last word of Jesus on the Cross, according to the Gospel of John?', options: ['"Meu Deus, por que me abandonaste?"', '"Pai, nas tuas mãos entrego o meu espírito"', '"Está consumado"', '"Tenho sede"'], optionsEn: ['"My God, why have you forsaken me?"', '"Father, into your hands I commit my spirit"', '"It is finished"', '"I thirst"'], correct: 2, why: 'João 19,30: "Quando Jesus tomou o vinagre, disse: Está consumado! E, inclinando a cabeça, entregou o espírito." O grego "tetelestai" significa obra completada. Mateus/Marcos registram o clamor do Sl 22; Lucas o "Pai, entrego".', whyEn: 'John 19:30: "When Jesus had received the sour wine, he said, It is finished, and he bowed his head and gave up his spirit." The Greek "tetelestai" means a completed work. Matthew/Mark record the Psalm 22 cry; Luke the "Father, into your hands".' },
  { id: 'dq-054', question: 'O que é o "tempo comum" no calendário litúrgico?', questionEn: 'What is "Ordinary Time" in the liturgical calendar?', options: ['Os períodos sem importância no ano litúrgico', 'Os períodos do ano litúrgico que não estão em Advento, Natal, Quaresma ou Páscoa', 'O tempo após Pentecostes até o Advento apenas', 'Qualquer período em que a Missa pode ser celebrada de forma simplificada'], optionsEn: ['Unimportant periods in the liturgical year', 'Periods of the liturgical year not in Advent, Christmas, Lent, or Easter', 'The time from Pentecost to Advent only', 'Any period when Mass may be celebrated in simplified form'], correct: 1, why: 'O Tempo Comum (anteriormente "Tempo depois de Pentecostes/Epifania") é o período ordinário do crescimento cristão. A cor é verde (esperança). Representa ~33 semanas do ano, celebrando a totalidade do mistério de Cristo.', whyEn: 'Ordinary Time (formerly "Time after Pentecost/Epiphany") is the ordinary period of Christian growth. The color is green (hope). It represents ~33 weeks of the year, celebrating the totality of the mystery of Christ.' },
  { id: 'dq-055', question: 'Quem é Nossa Senhora de Guadalupe e por que é importante?', questionEn: 'Who is Our Lady of Guadalupe and why is she important?', options: ['Uma imagem medieval europeia levada para o México', 'Maria, que apareceu em 1531 ao índio Juan Diego, deixando imagem miraculosa na tilma; patrona das Américas', 'Uma santa mexicana do séc. XVI', 'Uma aparição não reconhecida pela Igreja'], optionsEn: ['A medieval European image brought to Mexico', 'Mary, who appeared in 1531 to the Indian Juan Diego, leaving a miraculous image on his tilma; patroness of the Americas', 'A Mexican saint of the 16th century', 'An apparition not recognized by the Church'], correct: 1, why: 'Em 1531, Maria apareceu ao indígena Juan Diego em Tepeyac, México. A imagem impressa na tilma é inexplicável cientificamente (sem pinceladas, camadas de tinta, com estrelas que correspondem ao céu de 1531). A devoção converteu milhões de nativos.', whyEn: 'In 1531, Mary appeared to the indigenous Juan Diego at Tepeyac, Mexico. The image imprinted on the tilma is scientifically inexplicable (no brushstrokes, paint layers, with stars that correspond to the sky of 1531). The devotion converted millions of natives.' },
  { id: 'dq-056', question: 'O que é a "Lectio Continua" na liturgia?', questionEn: 'What is "Lectio Continua" in the liturgy?', options: ['A leitura seguida e contínua de livros bíblicos ao longo do ano litúrgico', 'A repetição dos mesmos textos todos os domingos', 'A leitura em voz alta de toda a Bíblia em um único culto', 'O estudo bíblico em grupo'], optionsEn: ['The sequential reading of biblical books throughout the liturgical year', 'The repetition of the same texts every Sunday', 'The reading aloud of the entire Bible in a single service', 'Bible study in a group'], correct: 0, why: 'A lectio continua é a prática de ler os livros bíblicos em sequência ao longo do ano, garantindo que a comunidade seja exposta a toda a Escritura. O lecionário atual da Missa cobre grande parte da Bíblia em 3 anos.', whyEn: 'Lectio continua is the practice of reading biblical books sequentially throughout the year, ensuring the community is exposed to all of Scripture. The current Mass lectionary covers most of the Bible in a 3-year cycle.' },
  { id: 'dq-057', question: 'Qual é o nome do documento que o Papa Bento XVI escreveu sobre o amor de Deus?', questionEn: 'What is the name of the document Pope Benedict XVI wrote about God\'s love?', options: ['Laudato Si', 'Deus Caritas Est', 'Evangelii Gaudium', 'Amoris Laetitia'], optionsEn: ['Laudato Si', 'Deus Caritas Est', 'Evangelii Gaudium', 'Amoris Laetitia'], correct: 1, why: '"Deus Caritas Est" (Deus é Amor, 2005) foi a primeira encíclica de Bento XVI. Explora o amor divino (ágape) e humano (eros) e a missão da caridade da Igreja. Baseada em 1 João 4,16: "Deus é amor".', whyEn: '"Deus Caritas Est" (God Is Love, 2005) was Benedict XVI\'s first encyclical. It explores divine love (agape) and human love (eros) and the Church\'s mission of charity. Based on 1 John 4:16: "God is love".' },
  { id: 'dq-058', question: 'O que é o "Exame de Consciência" como prática espiritual?', questionEn: 'What is the "Examination of Conscience" as a spiritual practice?', options: ['Uma lista de pecados para memorizar', 'Uma revisão diária da própria vida à luz de Deus, identificando graças e falhas', 'Uma avaliação psicológica da personalidade', 'O ato de confessar pecados ao padre'], optionsEn: ['A list of sins to memorize', 'A daily review of one\'s life in the light of God, identifying graces and failures', 'A psychological personality assessment', 'The act of confessing sins to a priest'], correct: 1, why: 'O Exame de Consciência (ou Examen inaciano) foi sistematizado por Inácio de Loyola nos Exercícios Espirituais. Envolve: gratidão, revisão do dia, sentimentos, perdão, esperança para amanhã. É preparação para a Confissão e crescimento espiritual.', whyEn: 'The Examination of Conscience (or Ignatian Examen) was systematized by Ignatius of Loyola in the Spiritual Exercises. It involves: gratitude, review of the day, feelings, forgiveness, hope for tomorrow. It prepares for Confession and spiritual growth.' },
  { id: 'dq-059', question: 'Em qual nação Moisés recebeu os Dez Mandamentos?', questionEn: 'On which mountain did Moses receive the Ten Commandments?', options: ['Monte das Oliveiras', 'Monte Sião', 'Monte Sinai', 'Monte Carmelo'], optionsEn: ['Mount of Olives', 'Mount Zion', 'Mount Sinai', 'Mount Carmel'], correct: 2, why: 'Êxodo 19-20: Moisés recebeu a Lei no Monte Sinai (também chamado Horeb). A aliança sinaítica estabeleceu Israel como povo de Deus. Os 10 Mandamentos são a base da moral judaica e cristã.', whyEn: 'Exodus 19-20: Moses received the Law at Mount Sinai (also called Horeb). The Sinai covenant established Israel as God\'s people. The 10 Commandments are the basis of Jewish and Christian morality.' },
  { id: 'dq-060', question: 'Qual é a principal diferença entre Católicos e Protestantes na visão da justificação?', questionEn: 'What is the main difference between Catholics and Protestants in the view of justification?', options: ['Católicos negam que a fé seja necessária; protestantes a exigem', 'Protestantes ensinam justificação por fé somente (forense); Católicos ensinam justificação que realmente transforma (ontológica) pela fé e cooperação', 'Não há diferença significativa hoje', 'Católicos aceitam mais pecados como perdoáveis'], optionsEn: ['Catholics deny faith is necessary; Protestants require it', 'Protestants teach justification by faith alone (forensic); Catholics teach justification that truly transforms (ontological) through faith and cooperation', 'There is no significant difference today', 'Catholics accept more sins as forgivable'], correct: 1, why: 'Lutero: a justificação é forense (declaração legal de inocência). Trento: a justificação realmente muda o interior do crente (regeneração). A Declaração Conjunta sobre Justificação (1999) encontrou amplo acordo, mas diferenças permanecem.', whyEn: 'Luther: justification is forensic (legal declaration of innocence). Trent: justification truly changes the believer\'s interior (regeneration). The Joint Declaration on Justification (1999) found broad agreement, but differences remain.' },
  { id: 'dq-061', question: 'O que é o "advento" em sentido teológico?', questionEn: 'What is "advent" in the theological sense?', options: ['A chegada de um dignitário eclesiástico', 'A vinda ou chegada de Cristo — primeira (encarnação) e segunda (parousia)', 'A preparação para uma missão', 'O início do ano eclesiástico apenas'], optionsEn: ['The arrival of an ecclesiastical dignitary', 'The coming or arrival of Christ — first (incarnation) and second (parousia)', 'The preparation for a mission', 'The beginning of the ecclesiastical year only'], correct: 1, why: '"Adventus" é o latim de "parousia" (chegada, presença). O Advento celebra as duas vindas de Cristo: a primeira, já realizada na Encarnação; a segunda, esperada no fim dos tempos. É tempo de espera ativa e conversão.', whyEn: '"Adventus" is the Latin for "parousia" (coming, presence). Advent celebrates Christ\'s two comings: the first, already realized in the Incarnation; the second, awaited at the end of time. It is a time of active waiting and conversion.' },
  { id: 'dq-062', question: 'Qual milagre é narrado em todos os quatro Evangelhos?', questionEn: 'Which miracle is narrated in all four Gospels?', options: ['A ressurreição de Lázaro', 'A cura de um cego', 'A multiplicação dos pães', 'Jesus caminhando sobre as águas'], optionsEn: ['The raising of Lazarus', 'The healing of a blind man', 'The multiplication of the loaves', 'Jesus walking on water'], correct: 2, why: 'A multiplicação dos pães e dos peixes aparece nos quatro Evangelhos (Mt 14; Mc 6; Lc 9; Jo 6). Sendo o único milagre relatado por todos os quatro, deve ter deixado uma impressão extraordinária nos primeiros discípulos.', whyEn: 'The multiplication of loaves and fish appears in all four Gospels (Mt 14; Mk 6; Lk 9; Jn 6). Being the only miracle recorded by all four, it must have left an extraordinary impression on the first disciples.' },
  { id: 'dq-063', question: 'Qual é o nome do anjo que anunciou o nascimento de Jesus a Maria?', questionEn: 'What is the name of the angel who announced the birth of Jesus to Mary?', options: ['Miguel', 'Rafael', 'Gabriel', 'Uriel'], optionsEn: ['Michael', 'Raphael', 'Gabriel', 'Uriel'], correct: 2, why: 'Gabriel (Lc 1,26) foi enviado a Nazaré para anunciar a Maria. Gabriel também interpretou as visões de Daniel (Dn 8-9) e anunciou a Zacarias o nascimento de João Batista (Lc 1,11-20).', whyEn: 'Gabriel (Lk 1:26) was sent to Nazareth to announce to Mary. Gabriel also interpreted Daniel\'s visions (Dn 8-9) and announced to Zechariah the birth of John the Baptist (Lk 1:11-20).' },
  { id: 'dq-064', question: 'Qual é a diferença entre "contemplação" e "meditação" na tradição espiritual cristã?', questionEn: 'What is the difference between "contemplation" and "meditation" in Christian spiritual tradition?', options: ['São sinônimos', 'Meditação é pensar reflexivamente sobre verdades religiosas; contemplação é presença amorosa e silenciosa a Deus além dos conceitos', 'Meditação é mais profunda que contemplação', 'Contemplação é apenas para religiosos e contemplativos'], optionsEn: ['They are synonyms', 'Meditation is reflective thinking about religious truths; contemplation is loving, silent presence to God beyond concepts', 'Meditation is deeper than contemplation', 'Contemplation is only for religious and contemplatives'], correct: 1, why: 'Na tradição mística (João da Cruz, Teresa de Ávila), meditação usa razão e imaginação para encontrar Deus nas verdades reveladas. Contemplação é dom de Deus — presença silenciosa e amorosa que vai além dos discursos mentais.', whyEn: 'In the mystical tradition (John of the Cross, Teresa of Ávila), meditation uses reason and imagination to find God in revealed truths. Contemplation is God\'s gift — silent, loving presence that goes beyond mental discourses.' },
  { id: 'dq-065', question: 'Qual é o papel de Nossa Senhora na Redenção, segundo a teologia católica?', questionEn: 'What is Our Lady\'s role in Redemption, according to Catholic theology?', options: ['Maria co-redimiu a humanidade igualmente a Jesus', 'Maria cooperou na Redenção de forma subordinada a Cristo, como "corredenora" e intercessora', 'Maria não tem papel teológico na Redenção', 'Maria é a quarta pessoa da Trindade'], optionsEn: ['Mary co-redeemed humanity equally to Jesus', 'Mary cooperated in Redemption in a subordinate way to Christ, as "co-redemptrix" and intercessor', 'Mary has no theological role in Redemption', 'Mary is the fourth person of the Trinity'], correct: 1, why: 'A teologia católica (não dogma) usa "corredenora" para indicar que Maria cooperou com o Redentor de forma subordinada — seu "sim" (fiat) permitiu a Encarnação. Só Cristo é o Redentor único; Maria intercede com Ele.', whyEn: 'Catholic theology (not dogma) uses "co-redemptrix" to indicate Mary cooperated with the Redeemer in a subordinate way — her "yes" (fiat) allowed the Incarnation. Only Christ is the unique Redeemer; Mary intercedes with Him.' },
  { id: 'dq-066', question: 'O que celebra a Solenidade de Todos os Santos (1° de novembro)?', questionEn: 'What does the Solemnity of All Saints (November 1) celebrate?', options: ['Os mártires cristãos apenas', 'Todos os santos canonizados e os que estão no Céu, conhecidos ou desconhecidos', 'Os fiéis defuntos que estão no purgatório', 'Os anjos e arcanjos'], optionsEn: ['Christian martyrs only', 'All canonized saints and those in Heaven, known or unknown', 'The faithful departed who are in purgatory', 'Angels and archangels'], correct: 1, why: 'A festa de Todos os Santos honra a Comunhão dos Santos — a multidão incontável do Céu (Ap 7,9). O dia seguinte (2 de novembro) é a Comemoração dos Fiéis Defuntos (finados), quando rezamos pelos que estão no purgatório.', whyEn: 'The feast of All Saints honors the Communion of Saints — the uncountable multitude in Heaven (Rev 7:9). The following day (November 2) is the Commemoration of All the Faithful Departed (All Souls), when we pray for those in purgatory.' },
  { id: 'dq-067', question: 'Qual é o gesto litúrgico mais antigo e universal do culto cristão?', questionEn: 'What is the oldest and most universal liturgical gesture in Christian worship?', options: ['O sinal da cruz', 'Ajoelhar-se', 'As mãos postas em oração', 'O beijo da paz'], optionsEn: ['The Sign of the Cross', 'Kneeling', 'Hands joined in prayer', 'The kiss of peace'], correct: 0, why: 'O sinal da cruz é attestado desde o séc. II (Tertuliano). Professa a Trindade (em nome do Pai, do Filho e do Espírito Santo) e a Redenção (na Cruz). É o primeiro e último gesto litúrgico da Missa e dos sacramentos.', whyEn: 'The Sign of the Cross is attested since the 2nd century (Tertullian). It professes the Trinity (in the name of the Father, Son, and Holy Spirit) and the Redemption (on the Cross). It is the first and last liturgical gesture of the Mass and sacraments.' },
  { id: 'dq-068', question: 'O que é a "kénosis" de Cristo?', questionEn: 'What is Christ\'s "kenosis"?', options: ['Sua transfiguração no Monte Tabor', 'O esvaziamento voluntário de privilégios divinos ao se tornar homem (Fl 2,7)', 'Sua morte na Cruz', 'Sua descida ao inferno'], optionsEn: ['His transfiguration on Mount Tabor', 'The voluntary emptying of divine privileges in becoming man (Phil 2:7)', 'His death on the Cross', 'His descent to hell'], correct: 1, why: 'Filipenses 2,7: Cristo "esvaziou-se a si mesmo, tomando a condição de servo". A kénosis (do grego "esvaziamento") não implica que o Filho deixou de ser Deus, mas que aceitou as limitações humanas por amor.', whyEn: 'Philippians 2:7: Christ "emptied himself, taking the form of a servant". Kenosis (from Greek "emptying") does not imply the Son ceased to be God, but that he accepted human limitations out of love.' },
  { id: 'dq-069', question: 'Qual é a posição da Igreja Católica sobre a pena de morte?', questionEn: 'What is the Catholic Church\'s position on capital punishment?', options: ['É sempre moralmente justificada para crimes graves', 'É inadmissível, pois atenta contra a inviolabilidade da dignidade humana (CIC §2267, rev. 2018)', 'É um assunto puramente político, sem posição oficial da Igreja', 'É permitida em casos de guerras justas'], optionsEn: ['It is always morally justified for serious crimes', 'It is inadmissible, as it attacks the inviolability of human dignity (CCC §2267, rev. 2018)', 'It is a purely political matter, with no official Church position', 'It is permitted in cases of just wars'], correct: 1, why: 'Em 2018, Francisco aprovou a revisão do CIC §2267: "a pena de morte é inadmissível porque atenta contra a inviolabilidade e dignidade da pessoa". A posição evoluiu historicamente — admitida em casos extremos anteriormente.', whyEn: 'In 2018, Francis approved the revision of CCC §2267: "the death penalty is inadmissible because it is an attack on the inviolability and dignity of the person". The position evolved historically — previously admitted in extreme cases.' },
  { id: 'dq-070', question: 'Qual livro bíblico descreve a criação com a imagem de Deus "modelando" o homem do barro?', questionEn: 'Which biblical book describes creation with the image of God "forming" man from clay?', options: ['Gênesis 1', 'Gênesis 2', 'Jó', 'Salmo 139'], optionsEn: ['Genesis 1', 'Genesis 2', 'Job', 'Psalm 139'], correct: 1, why: 'Gênesis 2,7: "o Senhor Deus modelou o homem com o pó da terra e insuflou nas suas narinas o fôlego de vida". Gênesis 1 usa "Deus disse... haja..."; Gênesis 2 usa a imagem mais íntima do oleiro.', whyEn: 'Genesis 2:7: "the Lord God formed the man of dust from the ground and breathed into his nostrils the breath of life". Genesis 1 uses "God said... let there be..."; Genesis 2 uses the more intimate image of the potter.' },
  { id: 'dq-071', question: 'Qual é o objetivo final da vida cristã, segundo o Catecismo da Igreja Católica?', questionEn: 'What is the ultimate goal of Christian life, according to the Catechism of the Catholic Church?', options: ['Ser uma boa pessoa e ajudar os outros', 'A visão beatífica — ver a Deus face a face e participar da vida divina por toda a eternidade', 'Alcançar a paz interior e o equilíbrio', 'Praticar os sacramentos e cumprir as obrigações religiosas'], optionsEn: ['Being a good person and helping others', 'The beatific vision — seeing God face to face and sharing divine life for all eternity', 'Achieving inner peace and balance', 'Practicing the sacraments and fulfilling religious obligations'], correct: 1, why: 'CIC §1720: o bem-aventurado vê a Deus face a face e participa, pela graça, da vida divina. "Tudo pela graça de Cristo" (§1721). O Catecismo começa: "Deus, sendo infinitamente perfeito e bem-aventurado em si mesmo, criou o homem para que participasse da sua beatitude."', whyEn: 'CCC §1720: the blessed see God face to face and share, by grace, in divine life. The Catechism begins: "God, infinitely perfect and blessed in himself... in a plan of sheer goodness freely created man to make him share in his own blessed life."' },
  { id: 'dq-072', question: 'Quantas tentações sofreu Jesus no deserto e quais foram?', questionEn: 'How many temptations did Jesus face in the desert and what were they?', options: ['Duas: riqueza e poder', 'Três: transformar pedras em pão, atirar-se do templo e adorar o diabo em troca de todos os reinos', 'Quatro: as mesmas de Israel no deserto', 'Cinco: as listas variam entre Evangelhos'], optionsEn: ['Two: wealth and power', 'Three: turning stones to bread, throwing himself from the temple, and worshipping the devil in exchange for all kingdoms', 'Four: the same as Israel in the desert', 'Five: the lists vary among Gospels'], correct: 1, why: 'Mateus 4,1-11 e Lucas 4,1-13 narram três tentações: pão (satisfação física/consumismo), tirar-se do templo (presunção/tentação a Deus), e todos os reinos (poder/idolatria). Correspondem às concupiscências (1 Jo 2,16).', whyEn: 'Matthew 4:1-11 and Luke 4:1-13 recount three temptations: bread (physical satisfaction/consumerism), throwing himself from the temple (presumption/testing God), and all the kingdoms (power/idolatry). They correspond to the concupiscences (1 Jn 2:16).' },
  { id: 'dq-073', question: 'O que é a "Comunhão dos Santos"?', questionEn: 'What is the "Communion of Saints"?', options: ['O grupo de pessoas canonizadas pela Igreja', 'A unidade espiritual entre todos os fiéis — vivos na terra, no purgatório e no céu — que compartilham os bens espirituais', 'A distribuição da Eucaristia', 'Uma antiga heresia'], optionsEn: ['The group of people canonized by the Church', 'The spiritual unity among all the faithful — living on earth, in purgatory, and in heaven — sharing spiritual goods', 'The distribution of the Eucharist', 'An ancient heresy'], correct: 1, why: 'O Credo Apostólico afirma "a comunhão dos santos". O Catecismo (§948) explica: unidade entre os santos do céu, do purgatório e da terra. Inclui a partilha de bens espirituais e a intercessão mútua.', whyEn: 'The Apostles\' Creed affirms "the communion of saints". The Catechism (§948) explains: unity among the saints in heaven, purgatory, and on earth. It includes sharing spiritual goods and mutual intercession.' },
  { id: 'dq-074', question: 'Qual é o "novo mandamento" que Jesus deu na Última Ceia?', questionEn: 'What is the "new commandment" Jesus gave at the Last Supper?', options: ['Amar a Deus acima de tudo', 'Amar-vos uns aos outros como Eu vos amei', 'Batizai todas as nações', 'Guardar o domingo santificado'], optionsEn: ['Love God above all things', 'Love one another as I have loved you', 'Baptize all nations', 'Keep Sunday holy'], correct: 1, why: 'João 13,34: "Dou-vos um mandamento novo: amai-vos uns aos outros; assim como eu vos amei, amai-vos também uns aos outros." É "novo" não porque fosse inédito (Lv 19,18), mas pelo novo padrão: "como Eu vos amei".', whyEn: 'John 13:34: "A new commandment I give to you, that you love one another: just as I have loved you, you also are to love one another." It is "new" not because it was unprecedented (Lv 19:18), but because of the new standard: "as I have loved you".' },
  { id: 'dq-075', question: 'Qual foi a primeira aparição de Maria reconhecida pela Igreja Católica?', questionEn: 'What was the first Marian apparition recognized by the Catholic Church?', options: ['Fátima (1917)', 'Lourdes (1858)', 'Guadalupe (1531)', 'Rue du Bac, Paris (1830)'], optionsEn: ['Fatima (1917)', 'Lourdes (1858)', 'Guadalupe (1531)', 'Rue du Bac, Paris (1830)'], correct: 2, why: 'Guadalupe (1531) é cronologicamente a mais antiga aparição mariana amplamente reconhecida, seguida por Rue du Bac (1830, Medalha Milagrosa), Lourdes (1858) e Fátima (1917).', whyEn: 'Guadalupe (1531) is chronologically the oldest widely recognized Marian apparition, followed by Rue du Bac (1830, Miraculous Medal), Lourdes (1858), and Fatima (1917).' },
  { id: 'dq-076', question: 'O que é a "parusia"?', questionEn: 'What is the "parousia"?', options: ['A festa de Pentecostes', 'A segunda vinda gloriosa de Cristo no fim dos tempos', 'A presença de Cristo na Eucaristia', 'A morte de um papa'], optionsEn: ['The feast of Pentecost', 'The glorious second coming of Christ at the end of time', 'The presence of Christ in the Eucharist', 'The death of a pope'], correct: 1, why: '"Parousia" (em grego: presença/chegada) refere-se à segunda vinda de Cristo (Mt 24,27-31). Será visível, gloriosa e definitiva, marcando o julgamento final, a ressurreição dos mortos e o estabelecimento do Reino eterno.', whyEn: '"Parousia" (in Greek: presence/coming) refers to Christ\'s second coming (Mt 24:27-31). It will be visible, glorious, and definitive, marking the final judgment, the resurrection of the dead, and the establishment of the eternal Kingdom.' },
  { id: 'dq-077', question: 'Qual é a mensagem de Fátima (1917) em síntese?', questionEn: 'What is the message of Fatima (1917) in summary?', options: ['Anunciar o fim do mundo iminente', 'Oração (especialmente o Rosário), penitência, conversão e consagração ao Imaculado Coração de Maria', 'Reformar a Igreja segundo visões apocalípticas', 'Revelar novos dogmas marianos'], optionsEn: ['Announce the imminent end of the world', 'Prayer (especially the Rosary), penance, conversion, and consecration to the Immaculate Heart of Mary', 'Reform the Church according to apocalyptic visions', 'Reveal new Marian dogmas'], correct: 1, why: 'Maria apareceu seis vezes a Lúcia, Francisco e Jacinta (maio-outubro 1917). Pediu Rosário diário, reparação, consagração da Rússia. Os três segredos incluem visão do inferno, a guerra, e o atentado ao papa. Reconhecida pela Igreja em 1930.', whyEn: 'Mary appeared six times to Lucia, Francisco, and Jacinta (May-October 1917). She requested daily Rosary, reparation, and consecration of Russia. The three secrets include a vision of hell, the war, and the assassination attempt on the pope. Recognized by the Church in 1930.' },
  { id: 'dq-078', question: 'O que Jesus disse a Nicodemos sobre o novo nascimento (Jo 3)?', questionEn: 'What did Jesus say to Nicodemus about being born again (Jn 3)?', options: ['Que só os judeus podem ser salvos', 'Que é preciso nascer de novo "de água e do Espírito" para entrar no Reino de Deus', 'Que basta crer sinceramente para ser salvo', 'Que a Torá é o único caminho'], optionsEn: ['That only Jews can be saved', 'That one must be born again "of water and the Spirit" to enter the Kingdom of God', 'That sincere belief alone is enough to be saved', 'That the Torah is the only way'], correct: 1, why: 'João 3,5: "Se alguém não renascer da água e do Espírito, não pode entrar no Reino de Deus." A tradição católica vê aqui a necessidade do Batismo. "Nascer de novo" indica transformação radical, não apenas nova mentalidade.', whyEn: 'John 3:5: "Unless one is born of water and the Spirit, he cannot enter the kingdom of God." Catholic tradition sees here the necessity of Baptism. "Born again" indicates radical transformation, not just a new mindset.' },
  { id: 'dq-079', question: 'Qual é o papel dos anjos na teologia católica?', questionEn: 'What is the role of angels in Catholic theology?', options: ['São a fé em anjos opcional e periférica', 'São seres espirituais criados, mensageiros de Deus, adoradores e protetores dos humanos (anjos da guarda)', 'São antigas pessoas que morreram e foram elevadas', 'São símbolos poéticos das ações divinas'], optionsEn: ['Belief in angels is optional and peripheral', 'They are created spiritual beings, God\'s messengers, worshippers, and protectors of humans (guardian angels)', 'They are ancient people who died and were elevated', 'They are poetic symbols of divine actions'], correct: 1, why: 'O Catecismo (§328-336) ensina que anjos são criaturas puramente espirituais, criados antes do mundo visível, que adoram a Deus, comunicam sua vontade e protegem os humanos. "Cada fiel tem um anjo da guarda" (CIC §336).', whyEn: 'The Catechism (§328-336) teaches that angels are purely spiritual creatures, created before the visible world, who adore God, communicate his will, and protect humans. "Every person has a guardian angel" (CCC §336).' },
  { id: 'dq-080', question: 'O que é o "Credo Niceno-Constantinopolitano"?', questionEn: 'What is the "Nicene-Constantinopolitan Creed"?', options: ['A versão curta do Credo rezada nas Missas dominicais', 'A profissão de fé elaborada nos Concílios de Nicéia (325) e Constantinopla I (381) e recitada na Missa', 'Um documento medieval sobre os papas', 'Uma oração particular de São Nicéforo'], optionsEn: ['The short version of the Creed prayed at Sunday Mass', 'The profession of faith elaborated at the Councils of Nicaea (325) and Constantinople I (381) and recited at Mass', 'A medieval document about the popes', 'A private prayer by St. Nicephorus'], correct: 1, why: 'O Credo Niceno-Constantinopolitano é a profissão de fé da Igreja Universal, recitada nas Missas dominicais. Define a consubstancialidade do Filho (Nicéia) e a divindade do Espírito Santo (Constantinopla).', whyEn: 'The Nicene-Constantinopolitan Creed is the profession of faith of the Universal Church, recited at Sunday Masses. It defines the consubstantiality of the Son (Nicaea) and the divinity of the Holy Spirit (Constantinople).' },
  { id: 'dq-081', question: 'Qual é a principal diferença entre a Páscoa judaica e a Páscoa cristã?', questionEn: 'What is the main difference between the Jewish Passover and the Christian Easter?', options: ['Não há diferença — são a mesma festa', 'A Páscoa judaica celebra a libertação do Egito; a cristã celebra a Ressurreição de Cristo, cumprimento e superação da primeira', 'A Páscoa cristã é anterior à judaica', 'A Páscoa judaica não tem caráter religioso'], optionsEn: ['There is no difference — they are the same feast', 'The Jewish Passover celebrates liberation from Egypt; the Christian celebrates the Resurrection of Christ, fulfillment and surpassing of the first', 'The Christian Easter predates the Jewish Passover', 'The Jewish Passover has no religious character'], correct: 1, why: 'A Páscoa judaica (Pessach) celebra a saída do Egito. Jesus morreu na Páscoa judaica, tornando-se o "Cordeiro de Deus" (1 Cor 5,7: "Cristo, nossa Páscoa, foi imolado"). A Ressurreição é a nova e definitiva passagem da morte para a vida.', whyEn: 'The Jewish Passover (Pesach) celebrates the Exodus from Egypt. Jesus died at Passover, becoming the "Lamb of God" (1 Cor 5:7: "Christ, our Passover lamb, has been sacrificed"). The Resurrection is the new and definitive passage from death to life.' },
  { id: 'dq-082', question: 'O que é o jejum eucarístico?', questionEn: 'What is the Eucharistic fast?', options: ['Abster-se da Eucaristia por 40 dias', 'Abster-se de alimentos e bebidas (exceto água e medicamentos) por uma hora antes da Comunhão', 'Não comer carne às sextas-feiras', 'Jejuar por 24 horas antes da confissão'], optionsEn: ['Abstaining from the Eucharist for 40 days', 'Abstaining from food and drink (except water and medicine) for one hour before Communion', 'Not eating meat on Fridays', 'Fasting for 24 hours before confession'], correct: 1, why: 'O atual jejum eucarístico (1964, Paulo VI) exige abstinência de alimentos e bebidas (exceto água e remédios) por uma hora antes da Comunhão. Antes era de 3 horas (Pio XII, 1953) e antes de meia-noite.', whyEn: 'The current Eucharistic fast (1964, Paul VI) requires abstaining from food and drink (except water and medicine) for one hour before Communion. Previously it was 3 hours (Pius XII, 1953) and before that from midnight.' },
  { id: 'dq-083', question: 'Qual é o sentido teológico do "sábado" no Antigo Testamento?', questionEn: 'What is the theological meaning of the "Sabbath" in the Old Testament?', options: ['Um dia de trabalho leve', 'O dia do descanso consagrado a Deus, em memória da criação e da aliança com Israel', 'Apenas uma norma higiênica', 'O dia de sacrifícios no templo'], optionsEn: ['A day of light work', 'The day of rest consecrated to God, in memory of creation and the covenant with Israel', 'Merely a hygienic norm', 'The day of temple sacrifices'], correct: 1, why: 'Gênesis 2,2-3 e Êxodo 20,8-11: o sábado é o sétimo dia, separado e consagrado. Memória da criação (Deus descansou) e da Aliança (Israel é povo de Deus). O domingo cristão é o "sábado escatológico" inaugurado pela Ressurreição.', whyEn: 'Genesis 2:2-3 and Exodus 20:8-11: the Sabbath is the seventh day, set apart and consecrated. Memory of creation (God rested) and of the Covenant (Israel is God\'s people). The Christian Sunday is the "eschatological Sabbath" inaugurated by the Resurrection.' },
  { id: 'dq-084', question: 'O que é a "Traditio Apostolica" de Hipólito de Roma?', questionEn: 'What is the "Traditio Apostolica" of Hippolytus of Rome?', options: ['Um documento sobre a sucessão papal', 'O mais antigo manual litúrgico preservado (~215 d.C.), com textos de ordenação, Eucaristia e outros ritos', 'Um tratado sobre heresías gnósticas', 'A primeira lista do cânon bíblico'], optionsEn: ['A document about papal succession', 'The oldest preserved liturgical manual (~215 AD), with texts of ordination, Eucharist, and other rites', 'A treatise on Gnostic heresies', 'The first list of the biblical canon'], correct: 1, why: 'A Traditio Apostolica (~215 d.C.) de Hipólito contém a mais antiga anáfora eucarística preservada, orações de ordenação episcopal, ritos de iniciação. É fonte fundamental para a liturgia do Vaticano II.', whyEn: 'The Traditio Apostolica (~215 AD) by Hippolytus contains the oldest preserved Eucharistic anaphora, prayers of episcopal ordination, and initiation rites. It is a fundamental source for the Vatican II liturgy.' },
  { id: 'dq-085', question: 'Qual é o pecado original em sua essência teológica?', questionEn: 'What is original sin in its theological essence?', options: ['Um pecado sexual cometido por Adão e Eva', 'A desobediência que rompeu a relação de Adão com Deus, transmitindo a toda a humanidade uma natureza ferida, privada da graça original', 'Um mito pedagógico sem realidade histórica', 'A inclinação ao mal apenas'], optionsEn: ['A sexual sin committed by Adam and Eve', 'The disobedience that broke Adam\'s relationship with God, transmitting to all humanity a wounded nature, deprived of original grace', 'A pedagogical myth without historical reality', 'Only the inclination toward evil'], correct: 1, why: 'O pecado original (Gn 3; Rm 5,12-19) não é um pecado sexual. É desobediência que privou Adão da graça santificante e transmitiu ao gênero humano uma natureza ferida. O Batismo remove a culpa; permanecem as sequelas (sofrimento, morte, concupiscência).', whyEn: 'Original sin (Gn 3; Rm 5:12-19) is not a sexual sin. It is disobedience that deprived Adam of sanctifying grace and transmitted to humanity a wounded nature. Baptism removes the guilt; the effects remain (suffering, death, concupiscence).' },
  { id: 'dq-086', question: 'Qual é a definição de "heresia" na teologia católica?', questionEn: 'What is the definition of "heresy" in Catholic theology?', options: ['Qualquer erro intelectual ou moral', 'A negação pertinaz, após o Batismo, de uma verdade que deve ser crida com fé divina e católica', 'A separação da autoridade eclesiástica sem negar doutrinas', 'A prática de magia ou ocultismo'], optionsEn: ['Any intellectual or moral error', 'The pertinacious denial, after Baptism, of a truth that must be believed with divine and catholic faith', 'Separation from ecclesiastical authority without denying doctrines', 'The practice of magic or occultism'], correct: 1, why: 'O CIC cânon 751 define heresia como negação pertinaz de uma verdade de fé. Apostasia é abandono total da fé; cisma é recusa à autoridade do papa. Heresia requer pertinácia (não mero erro de boa-fé).', whyEn: 'CIC canon 751 defines heresy as the pertinacious denial of a truth of faith. Apostasy is the total abandonment of faith; schism is the refusal of the pope\'s authority. Heresy requires pertinacity (not merely good-faith error).' },
  { id: 'dq-087', question: 'Qual é a posição da Igreja sobre a meditação budista (mindfulness)?', questionEn: 'What is the Church\'s position on Buddhist meditation (mindfulness)?', options: ['É proibida aos católicos', 'Técnicas de relaxamento e atenção plena podem ser usadas, mas devem ser integradas à oração cristã, evitando ideologias incompatíveis', 'É equivalente à lectio divina', 'A Igreja não tem posição sobre isso'], optionsEn: ['It is forbidden to Catholics', 'Relaxation and mindfulness techniques may be used, but must be integrated into Christian prayer, avoiding incompatible ideologies', 'It is equivalent to lectio divina', 'The Church has no position on this'], correct: 1, why: '"Orationis Formas" (1989, CDF) e o documento sobre Nova Era (2003) distinguem técnicas de relaxamento (neutras) de práticas ligadas a cosmovisões incompatíveis com o cristianismo (panteísmo, fusão com o cosmos).', whyEn: '"Orationis Formas" (1989, CDF) and the document on New Age (2003) distinguish relaxation techniques (neutral) from practices tied to worldviews incompatible with Christianity (pantheism, fusion with the cosmos).' },
  { id: 'dq-088', question: 'O que é o "exame de consciência" antes da Confissão?', questionEn: 'What is the "examination of conscience" before Confession?', options: ['Uma lista de pecados pré-impressa', 'Uma reflexão pessoal sobre os pecados cometidos desde a última confissão, à luz da lei de Deus e da Igreja', 'A absolvição geral dada antes do rito individual', 'Uma oração de ação de graças'], optionsEn: ['A pre-printed list of sins', 'A personal reflection on sins committed since the last confession, in light of God\'s and the Church\'s law', 'The general absolution given before individual rite', 'A prayer of thanksgiving'], correct: 1, why: 'O exame de consciência prepara a confissão: identificar pecados, sua gravidade e número aproximado. Baseia-se nos mandamentos, nas obras de misericórdia e nas circunstâncias de estado de vida. Objetivo: contrição sincera e confissão íntegra.', whyEn: 'The examination of conscience prepares confession: identifying sins, their gravity, and approximate number. It is based on the commandments, the works of mercy, and the circumstances of one\'s state of life. Goal: sincere contrition and integral confession.' },
  { id: 'dq-089', question: 'Qual é a distinção entre "fé" e "crença" na teologia católica?', questionEn: 'What is the distinction between "faith" and "belief" in Catholic theology?', options: ['São sinônimos sem distinção', 'Fé (fides) é uma virtude teologal infusa por Deus; crença pode ser apenas opinião humana sem fundamento sobrenatural', 'Fé é mais fraca que crença', 'Crença refere-se às práticas; fé às doutrinas'], optionsEn: ['They are synonyms with no distinction', 'Faith (fides) is a theological virtue infused by God; belief can be merely human opinion without supernatural foundation', 'Faith is weaker than belief', 'Belief refers to practices; faith to doctrines'], correct: 1, why: 'A fé teologal é dom de Deus (Ef 2,8) que permite ao fiel aderir às verdades reveladas com certeza. Não é mera opinião. O Catecismo (§153) define: "A fé é dom de Deus, virtude sobrenatural infusa por Ele".', whyEn: 'Theological faith is God\'s gift (Eph 2:8) that enables the faithful to adhere to revealed truths with certainty. It is not mere opinion. The Catechism (§153) defines: "Faith is a gift of God, a supernatural virtue infused by Him".' },
  { id: 'dq-090', question: 'O que é a "Sagrada Família" como modelo para as famílias cristãs?', questionEn: 'What is the "Holy Family" as a model for Christian families?', options: ['Um ideal inatingível e abstrato', 'Jesus, Maria e José como modelo de amor, obediência, trabalho e vida centrada em Deus para todas as famílias', 'Um símbolo medieval sem relevância atual', 'Apenas Maria e Jesus, sem José'], optionsEn: ['An unattainable and abstract ideal', 'Jesus, Mary, and Joseph as a model of love, obedience, work, and God-centered life for all families', 'A medieval symbol without contemporary relevance', 'Only Mary and Jesus, without Joseph'], correct: 1, why: 'A festa da Sagrada Família (domingo após o Natal) celebra Jesus, Maria e José em Nazaré. João Paulo II em "Familiaris Consortio" (1981) propôs a Sagrada Família como modelo: amor, respeito, trabalho, oração e obediência a Deus.', whyEn: 'The feast of the Holy Family (Sunday after Christmas) celebrates Jesus, Mary, and Joseph in Nazareth. John Paul II in "Familiaris Consortio" (1981) proposed the Holy Family as a model: love, respect, work, prayer, and obedience to God.' },
  { id: 'dq-091', question: 'Qual é o principal argumento filosófico a favor da existência de uma lei moral objetiva?', questionEn: 'What is the main philosophical argument in favor of the existence of an objective moral law?', options: ['A maioria das pessoas concorda com certos valores básicos', 'A consciência moral universal indica que há uma lei inscrita na razão humana (lei natural), apontando para um Legislador', 'As leis civis refletem a moral objetiva', 'Cada cultura tem seus próprios valores igualmente válidos'], optionsEn: ['Most people agree on certain basic values', 'Universal moral conscience indicates there is a law inscribed in human reason (natural law), pointing to a Lawgiver', 'Civil laws reflect objective morality', 'Each culture has equally valid values'], correct: 1, why: 'C. S. Lewis em "Mero Cristianismo" e Romanos 2,14-15 (lei nos corações dos gentios) argumentam que a consciência moral universal exige explicação: ou é ilusão evolutiva ou aponta para um Legislador transcendente.', whyEn: 'C. S. Lewis in "Mere Christianity" and Romans 2:14-15 (the law in the hearts of Gentiles) argue that universal moral conscience requires explanation: either it is an evolutionary illusion or it points to a transcendent Lawgiver.' },
  { id: 'dq-092', question: 'O que Jesus diz sobre o divórcio no Evangelho?', questionEn: 'What does Jesus say about divorce in the Gospel?', options: ['É permitido em casos de adultério e abandono', '"O que Deus uniu, o homem não separe" — indissolubilidade do matrimônio, com exceção apenas da porneia', 'O AT permite o divórcio e o NT não muda isso', 'É assunto da lei civil, não da religião'], optionsEn: ['It is permitted in cases of adultery and abandonment', '"What God has joined together, let no one separate" — indissolubility of marriage, with exception only for porneia', 'The OT permits divorce and the NT does not change this', 'It is a civil law matter, not religion'], correct: 1, why: 'Mateus 19,6.9; Marcos 10,9. Jesus revoga a permissão mosaica (Dt 24,1-4) e reafirma a lei original do Éden. A "exceção" de Mateus (porneia) é interpretada pela tradição como referindo-se a uniões ilegítimas, não ao casamento válido.', whyEn: 'Matthew 19:6,9; Mark 10:9. Jesus revokes the Mosaic permission (Dt 24:1-4) and reaffirms the original Eden law. The "exception clause" in Matthew (porneia) is interpreted by tradition as referring to illegitimate unions, not to a valid marriage.' },
  { id: 'dq-093', question: 'Qual apóstolo foi chamado de "coluna da Igreja" junto a Pedro e Tiago?', questionEn: 'Which apostle was called a "pillar of the Church" along with Peter and James?', options: ['Barnabé', 'João', 'André', 'Filippe'], optionsEn: ['Barnabas', 'John', 'Andrew', 'Philip'], correct: 1, why: 'Gálatas 2,9: Paulo menciona "Tiago, Cefas (Pedro) e João, que eram considerados colunas". João, filho de Zebedeu, foi um dos três apóstolos mais próximos de Jesus (junto a Pedro e Tiago) e o apóstolo amado.', whyEn: 'Galatians 2:9: Paul mentions "James and Cephas (Peter) and John, who seemed to be pillars". John, son of Zebedee, was one of the three apostles closest to Jesus (along with Peter and James) and the beloved apostle.' },
  { id: 'dq-094', question: 'O que é a "Nova Aliança" anunciada por Jeremias?', questionEn: 'What is the "New Covenant" announced by Jeremiah?', options: ['Uma aliança política entre Israel e Babilônia', 'Uma aliança em que Deus escreverá sua Lei no coração dos homens, não em pedra', 'Uma renovação da aliança mosaica com novas leis', 'A aliança que o Messias faria com os gentios apenas'], optionsEn: ['A political alliance between Israel and Babylon', 'A covenant in which God will write his Law on men\'s hearts, not on stone', 'A renewal of the Mosaic covenant with new laws', 'The covenant the Messiah would make with Gentiles only'], correct: 1, why: 'Jeremias 31,31-34: "Farei uma nova aliança... porei a minha lei no seu interior, escrevendo-a no seu coração." Jesus na Última Ceia disse: "Este cálice é a nova aliança no meu sangue" (Lc 22,20).', whyEn: 'Jeremiah 31:31-34: "I will make a new covenant... I will put my law within them, and I will write it on their hearts." Jesus at the Last Supper said: "This cup is the new covenant in my blood" (Lk 22:20).' },
  { id: 'dq-095', question: 'Qual é o significado do peixe (IXTHYS) como símbolo cristão primitivo?', questionEn: 'What is the meaning of the fish (IXTHYS) as an early Christian symbol?', options: ['Simbolizava que os primeiros cristãos eram pescadores', 'Era acrônimo grego de "Jesus Cristo, Filho de Deus, Salvador"', 'Era um sinal secreto para reuniões ilegais apenas', 'Representava a multiplicação dos pães e peixes'], optionsEn: ['It symbolized that early Christians were fishermen', 'It was a Greek acronym for "Jesus Christ, Son of God, Savior"', 'It was only a secret sign for illegal gatherings', 'It represented the multiplication of loaves and fish'], correct: 1, why: 'IXTHYS (ichtys = peixe em grego) = Iesous Christos Theou Yios Soter (Jesus Cristo, Filho de Deus, Salvador). Era um símbolo de identificação entre cristãos no período romano, anterior à Cruz como símbolo predominante.', whyEn: 'IXTHYS (ichthys = fish in Greek) = Iesous Christos Theou Yios Soter (Jesus Christ, Son of God, Savior). It was an identification symbol among Christians in the Roman period, predating the Cross as the predominant symbol.' },
  { id: 'dq-096', question: 'Qual é a diferença entre "latria" e "dulia"?', questionEn: 'What is the difference between "latria" and "dulia"?', options: ['São sinônimos em latim eclesiástico', 'Latria é adoração devida só a Deus; dulia é veneração dos santos; hyperdulia é veneração especial a Maria', 'Latria é oração pública; dulia é oração privada', 'Latria é para os sacramentos; dulia para as devoções'], optionsEn: ['They are synonyms in ecclesiastical Latin', 'Latria is worship due to God alone; dulia is veneration of saints; hyperdulia is special veneration of Mary', 'Latria is public prayer; dulia is private prayer', 'Latria is for sacraments; dulia for devotions'], correct: 1, why: 'Tomás de Aquino (ST II-II, q.84, a.1) explica: latria (adoração/culto) só a Deus; dulia (reverência/veneração) aos santos; hyperdulia a Maria. Essa distinção responde à acusação de idolatria: católicos não adoram santos.', whyEn: 'Thomas Aquinas (ST II-II, q.84, a.1) explains: latria (adoration/worship) to God alone; dulia (reverence/veneration) to saints; hyperdulia to Mary. This distinction answers the charge of idolatry: Catholics do not worship saints.' },
  { id: 'dq-097', question: 'Qual é o significado bíblico do nome "Emanuel"?', questionEn: 'What is the biblical meaning of the name "Emmanuel"?', options: ['Deus cura', 'Deus salva', 'Deus conosco', 'Deus forte'], optionsEn: ['God heals', 'God saves', 'God with us', 'God the Mighty'], correct: 2, why: '"Emanuel" vem do hebraico "Im-manu-El" (com-nós-Deus). Isaías 7,14 profetizou que um filho chamado Emanuel nasceria de uma virgem. Mateus 1,23 aplica isso a Jesus: "Deus conosco" é o tema central da Encarnação.', whyEn: '"Emmanuel" comes from the Hebrew "Im-manu-El" (with-us-God). Isaiah 7:14 prophesied that a son named Emmanuel would be born of a virgin. Matthew 1:23 applies this to Jesus: "God with us" is the central theme of the Incarnation.' },
  { id: 'dq-098', question: 'Qual é a principal distinção entre o catolicismo e a Ortodoxia no que se refere ao papado?', questionEn: 'What is the main distinction between Catholicism and Orthodoxy regarding the papacy?', options: ['A Ortodoxia aceita o papa como chefe supremo', 'A Ortodoxia reconhece ao Bispo de Roma uma primazia de honra, mas não jurisdição universal; o catolicismo ensina primazia de jurisdição', 'As duas Igrejas têm o mesmo ensinamento sobre o papa', 'A Ortodoxia tem um papa próprio em Constantinopla'], optionsEn: ['Orthodoxy accepts the pope as supreme head', 'Orthodoxy recognizes the Bishop of Rome a primacy of honor, but not universal jurisdiction; Catholicism teaches a primacy of jurisdiction', 'The two Churches have the same teaching about the pope', 'Orthodoxy has its own pope in Constantinople'], correct: 1, why: 'O Cisma de 1054 teve entre suas causas a questão do primado romano. A Ortodoxia aceita Pedro como primus inter pares (primeiro entre iguais), mas não a jurisdição universal do papa sobre todas as Igrejas. O Concílio de Florença (1439) tentou reunificação sem sucesso.', whyEn: 'The 1054 Schism had among its causes the question of Roman primacy. Orthodoxy accepts Peter as primus inter pares (first among equals), but not the universal jurisdiction of the pope over all Churches. The Council of Florence (1439) attempted reunification without success.' },
  { id: 'dq-099', question: 'Quem é considerado o "Pai da Igreja Latina" por excelência?', questionEn: 'Who is considered the "Father of the Latin Church" par excellence?', options: ['São Jerônimo', 'São Ambrósio', 'Santo Agostinho', 'São Gregório Magno'], optionsEn: ['St. Jerome', 'St. Ambrose', 'St. Augustine', 'St. Gregory the Great'], correct: 2, why: 'Agostinho de Hipona (354-430) é o maior teólogo da Igreja Latina. Suas obras (Confissões, Cidade de Deus, Trindade) definiram o pensamento cristão ocidental por mil anos. Lutero, Calvino e Jansénius todos se basearam em leituras (diferentes) de Agostinho.', whyEn: 'Augustine of Hippo (354-430) is the greatest theologian of the Latin Church. His works (Confessions, City of God, On the Trinity) defined Western Christian thought for a thousand years. Luther, Calvin, and Jansenius all based themselves on (different) readings of Augustine.' },
  { id: 'dq-100', question: 'O que significa "estar em estado de graça"?', questionEn: 'What does it mean to "be in a state of grace"?', options: ['Sentir paz interior e tranquilidade', 'Não ter pecados mortais na alma, estar em amizade com Deus por meio da graça santificante', 'Ter recebido todos os sacramentos da iniciação', 'Não ter cometido nenhum pecado venial recentemente'], optionsEn: ['Feeling inner peace and tranquility', 'Having no mortal sins on the soul, being in friendship with God through sanctifying grace', 'Having received all the sacraments of initiation', 'Not having committed any venial sins recently'], correct: 1, why: '"Estado de graça" significa ausência de pecado mortal e presença da graça santificante. É a condição para receber a Eucaristia dignamente (1 Cor 11,27-29) e para morrer em paz. O pecado mortal rompe esse estado; a Confissão o restaura.', whyEn: '"State of grace" means the absence of mortal sin and the presence of sanctifying grace. It is the condition for receiving the Eucharist worthily (1 Cor 11:27-29) and for dying in peace. Mortal sin breaks this state; Confession restores it.' },
];

// Escolhe quiz determinístico por dia (mesmo quiz pra todo mundo no mesmo dia).
export function getQuizOfDay(date = new Date()) {
  const start = new Date(date.getFullYear(), 0, 0);
  const dayOfYear = Math.floor((date - start) / (1000 * 60 * 60 * 24));
  const seed = (dayOfYear + date.getFullYear() * 13) % DAILY_QUESTIONS.length;
  return DAILY_QUESTIONS[seed];
}

// Escolhe N perguntas aleatórias (modo "praticar") sem repetir.
export function getRandomQuestions(n = 10) {
  const shuffled = [...QUIZ].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(n, QUIZ.length));
}

// Modo verdadeiro/falso: retorna N afirmações aleatórias.
export function getRandomTrueFalse(n = 10) {
  const shuffled = [...TRUE_FALSE].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(n, TRUE_FALSE.length));
}
